import React, { useState } from 'react';
import { Portfolio } from '../types';
import { Icons } from './Icons';
import { analyzePortfolioWithGemini } from '../services/geminiService';
import { AreaChart, Area, ResponsiveContainer } from 'recharts';

interface PortfolioCardProps {
  portfolio: Portfolio;
  onBack: (id: string) => void;
  isBacked: boolean;
}

const PortfolioCard: React.FC<PortfolioCardProps> = ({ portfolio, onBack, isBacked }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Generate simple sparkline data based on return
  const data = Array.from({ length: 10 }, (_, i) => ({
    val: 100 + (portfolio.totalReturn * (i / 10)) + (Math.random() * 2 - 1)
  }));

  const handleAiAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (aiAnalysis) return; // Already analyzed
    setLoadingAi(true);
    const result = await analyzePortfolioWithGemini(portfolio.stocks, portfolio.title);
    setAiAnalysis(result);
    setLoadingAi(false);
  };

  return (
    <div className="bg-alpha-card border border-gray-700 rounded-xl overflow-hidden hover:border-alpha-accent/50 transition-all duration-300 group">
      {/* Header */}
      <div className="p-4 border-b border-gray-700 flex justify-between items-start bg-gray-800/30">
        <div className="flex gap-3">
          <img src={portfolio.kolAvatar} alt={portfolio.kolName} className="w-10 h-10 rounded-full border border-gray-600" />
          <div>
            <h3 className="font-bold text-white text-sm group-hover:text-alpha-accent transition-colors">{portfolio.title}</h3>
            <div className="flex items-center gap-1 text-xs text-gray-400">
              <span>by {portfolio.kolName}</span>
              {portfolio.isVerifiedKOL && <Icons.ShieldCheck size={12} className="text-alpha-accent" />}
            </div>
          </div>
        </div>
        <div className={`px-2 py-1 rounded-md text-xs font-bold ${portfolio.totalReturn >= 0 ? 'bg-alpha-success/20 text-alpha-success' : 'bg-alpha-danger/20 text-alpha-danger'}`}>
          {portfolio.totalReturn >= 0 ? '+' : ''}{portfolio.totalReturn}%
        </div>
      </div>

      {/* Stocks Grid */}
      <div className="p-4 grid grid-cols-2 gap-2">
        {portfolio.stocks.map((stock) => (
          <div key={stock.ticker} className="bg-gray-800/50 p-2 rounded-lg flex justify-between items-center">
             <span className="font-bold text-xs text-gray-300">{stock.ticker}</span>
             <span className={`text-xs ${stock.changePercent >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
               {stock.changePercent > 0 ? '+' : ''}{stock.changePercent}%
             </span>
          </div>
        ))}
      </div>

      {/* Chart preview */}
      <div className="h-16 w-full opacity-50">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data}>
            <Area 
              type="monotone" 
              dataKey="val" 
              stroke={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} 
              fill={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} 
              fillOpacity={0.1} 
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* Footer / Actions */}
      <div className="p-4 border-t border-gray-700 space-y-3">
        {/* AI Analysis Section */}
        {aiAnalysis ? (
          <div className="p-3 bg-indigo-900/20 border border-indigo-500/20 rounded-lg">
             <div className="flex items-center gap-1 text-xs text-indigo-400 mb-1">
               <Icons.Zap size={12} /> AI Analyst
             </div>
             <p className="text-xs text-gray-300 leading-relaxed">{aiAnalysis}</p>
          </div>
        ) : (
          <button 
            onClick={handleAiAnalyze}
            disabled={loadingAi}
            className="w-full py-1.5 flex items-center justify-center gap-2 text-xs font-medium text-indigo-400 hover:text-indigo-300 transition-colors"
          >
            {loadingAi ? 'Analyzing...' : <><Icons.Zap size={14} /> Reveal AI Analysis</>}
          </button>
        )}

        <div className="flex justify-between items-center pt-2">
          <div className="flex items-center gap-1 text-xs text-gray-500">
             <Icons.Users size={12} /> {portfolio.backers} Backers
          </div>
          <button 
            onClick={() => onBack(portfolio.id)}
            disabled={isBacked}
            className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${
              isBacked 
                ? 'bg-gray-700 text-gray-400 cursor-not-allowed' 
                : 'bg-alpha-success hover:bg-green-600 text-white shadow-lg shadow-green-900/20'
            }`}
          >
            {isBacked ? 'Backed' : <>Back It <Icons.TrendingUp size={16} /></>}
          </button>
        </div>
      </div>
    </div>
  );
};

export default PortfolioCard;

import React, { useState, useEffect } from 'react';
import { WatchlistItem, Stock } from '../types';
import { Icons } from './Icons';
import { getSimulatedPriceUpdate, MOCK_STOCKS } from '../services/mockData';

interface WatchlistPanelProps {
  watchlist: WatchlistItem[];
  addToWatchlist: (ticker: string, qty: number, avgPrice: number) => void;
}

const WatchlistPanel: React.FC<WatchlistPanelProps> = ({ watchlist, addToWatchlist }) => {
  const [items, setItems] = useState<WatchlistItem[]>(watchlist);
  const [isAdding, setIsAdding] = useState(false);
  const [newTicker, setNewTicker] = useState('NVDA');
  const [newQty, setNewQty] = useState(1);
  const [newPrice, setNewPrice] = useState(0);

  // Effect to simulate live prices for watchlist
  useEffect(() => {
    const interval = setInterval(() => {
      setItems(prev => prev.map(item => ({
        ...item,
        currentPrice: getSimulatedPriceUpdate(item.currentPrice || item.avgPrice)
      })));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // Sync props to state if props change (initial load)
  useEffect(() => {
      setItems(watchlist.map(w => {
          // Find current price in mock data if not set
          const stock = MOCK_STOCKS.find(s => s.ticker === w.ticker);
          return { ...w, currentPrice: w.currentPrice || stock?.price || w.avgPrice };
      }));
  }, [watchlist]);

  const handleAdd = () => {
    addToWatchlist(newTicker, newQty, newPrice);
    setIsAdding(false);
    // Optimistic local update
    const stock = MOCK_STOCKS.find(s => s.ticker === newTicker);
    setItems([...items, {
        id: Date.now().toString(),
        ticker: newTicker,
        quantity: newQty,
        avgPrice: newPrice,
        currentPrice: stock ? stock.price : newPrice
    }]);
  };

  const calculateTotalPnL = () => {
    return items.reduce((acc, item) => {
        const current = item.currentPrice || item.avgPrice;
        return acc + ((current - item.avgPrice) * item.quantity);
    }, 0);
  };

  const totalPnL = calculateTotalPnL();

  return (
    <div className="space-y-6">
      <div className="bg-alpha-card rounded-2xl p-6 border border-gray-700">
        <div className="flex justify-between items-end mb-6">
          <div>
            <h2 className="text-gray-400 text-sm font-medium uppercase tracking-wider">Total P&L</h2>
            <div className={`text-3xl font-bold ${totalPnL >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
              {totalPnL >= 0 ? '+' : ''}${totalPnL.toFixed(2)}
            </div>
          </div>
          <button 
            onClick={() => setIsAdding(!isAdding)}
            className="bg-alpha-accent hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2"
          >
            <Icons.Plus size={16} /> Add Position
          </button>
        </div>

        {isAdding && (
          <div className="mb-6 p-4 bg-gray-800 rounded-xl border border-gray-600 animate-in fade-in slide-in-from-top-4">
            <h3 className="text-white font-bold mb-3">Add to Watchlist</h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-3">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Ticker</label>
                <select 
                    value={newTicker} 
                    onChange={(e) => {
                        setNewTicker(e.target.value);
                        const stock = MOCK_STOCKS.find(s => s.ticker === e.target.value);
                        if(stock) setNewPrice(stock.price);
                    }}
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-2 text-white"
                >
                    {MOCK_STOCKS.map(s => <option key={s.ticker} value={s.ticker}>{s.ticker}</option>)}
                </select>
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Quantity</label>
                <input 
                    type="number" 
                    value={newQty}
                    onChange={(e) => setNewQty(Number(e.target.value))}
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-2 text-white"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Avg Buy Price</label>
                <input 
                    type="number" 
                    value={newPrice}
                    onChange={(e) => setNewPrice(Number(e.target.value))}
                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-2 text-white"
                />
              </div>
            </div>
            <button onClick={handleAdd} className="w-full bg-alpha-success text-white py-2 rounded-lg font-bold">
                Confirm Add
            </button>
          </div>
        )}

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="border-b border-gray-700 text-xs text-gray-500 uppercase">
                <th className="pb-3">Ticker</th>
                <th className="pb-3 text-right">Qty</th>
                <th className="pb-3 text-right">Avg Price</th>
                <th className="pb-3 text-right">Current</th>
                <th className="pb-3 text-right">P&L</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-800">
              {items.map((item) => {
                const current = item.currentPrice || item.avgPrice;
                const pnl = (current - item.avgPrice) * item.quantity;
                const pnlPercent = ((current - item.avgPrice) / item.avgPrice) * 100;

                return (
                  <tr key={item.id} className="group hover:bg-gray-800/50 transition-colors">
                    <td className="py-4 font-bold text-white">{item.ticker}</td>
                    <td className="py-4 text-right text-gray-300">{item.quantity}</td>
                    <td className="py-4 text-right text-gray-400">${item.avgPrice.toFixed(2)}</td>
                    <td className="py-4 text-right text-white font-mono">${current.toFixed(2)}</td>
                    <td className="py-4 text-right">
                      <div className={`font-bold ${pnl >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                        {pnl >= 0 ? '+' : ''}{pnl.toFixed(2)}
                      </div>
                      <div className={`text-xs ${pnl >= 0 ? 'text-green-900' : 'text-red-900'} inline-block px-1 rounded`}>
                        {pnlPercent.toFixed(2)}%
                      </div>
                    </td>
                  </tr>
                );
              })}
              {items.length === 0 && (
                <tr>
                    <td colSpan={5} className="py-8 text-center text-gray-500 italic">
                        No stocks tracked yet. Add one above!
                    </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="p-4 bg-indigo-900/10 border border-indigo-500/20 rounded-xl">
          <div className="flex gap-3">
              <Icons.Zap className="text-alpha-accent shrink-0" />
              <div>
                  <h4 className="font-bold text-white text-sm">Pro Tip</h4>
                  <p className="text-xs text-gray-400 mt-1">
                      Tracking your real-world portfolio here lets you compare your performance against top KOLs directly.
                      See if you can beat the Alpha Seekers!
                  </p>
              </div>
          </div>
      </div>
    </div>
  );
};

