// This service simulates connecting to public APIs (Google Finance/Polygon/Yahoo)
// In a real app, this would make fetch() calls to those endpoints.
// Here, we simulate the latency and data structure.

const getRandomPrice = (min: number, max: number) => Number((Math.random() * (max - min) + min).toFixed(2));
const getRandomChange = () => Number((Math.random() * 6 - 3).toFixed(2)); // -3% to +3%

// Cache for consistent random data for unknown tickers during a session
const SESSION_CACHE: Record<string, Stock> = {};

export const fetchStockQuote = async (ticker: string): Promise<Stock> => {
  // Simulate API Latency
  await new Promise(resolve => setTimeout(resolve, 300));

  const upperTicker = ticker.toUpperCase();

  // 1. Try "Primary Source" (Our Mock Data)
  const existing = MOCK_STOCKS.find(s => s.ticker === upperTicker);
  if (existing) {
    return { ...existing };
  }

  // 2. Check Session Cache for unknown tickers we've already generated
  if (SESSION_CACHE[upperTicker]) {
    return { ...SESSION_CACHE[upperTicker] };
  }

  // 3. Fallback: Generate realistic mock data for ANY ticker entered
  // This simulates a successful fetch from an external provider like Polygon.io
  const newStock: Stock = {
    ticker: upperTicker,
    name: `${upperTicker} Corp`, // Placeholder name
    price: getRandomPrice(20, 450),
    changePercent: getRandomChange(),
    sector: 'Unknown'
  };

  SESSION_CACHE[upperTicker] = newStock;
  return newStock;
};

export const getLivePriceUpdate = (currentPrice: number): number => {
  const volatility = 0.003; // 0.3% movement max per tick
  const change = currentPrice * volatility * (Math.random() - 0.5);
  return Number((currentPrice + change).toFixed(2));
};

export const generateHistoricalData = (basePrice: number, points: number = 30) => {
  const data = [];
  let current = basePrice * 0.95; // Start slightly lower to show trend
  for (let i = 0; i < points; i++) {
    current = getLivePriceUpdate(current);
    data.push({
      time: `Day ${i + 1}`,
      value: current
    });
  }
  // Ensure the last point connects roughly to current price
  data[data.length - 1].value = basePrice;
  return data;
};

