import React, { useState, useEffect } from 'react';
import { WatchlistItem, ChartDataPoint } from '../types';
import { Icons } from './Icons';
import { fetchStockQuote, getLivePriceUpdate } from '../services/stockData';
import { AreaChart, Area, ResponsiveContainer, XAxis, YAxis, Tooltip } from 'recharts';

interface WatchlistPanelProps {
  watchlist: WatchlistItem[];
  addToWatchlist: (ticker: string, qty: number, avgPrice: number) => void;
}

const WatchlistPanel: React.FC<WatchlistPanelProps> = ({ watchlist, addToWatchlist }) => {
  const [items, setItems] = useState<WatchlistItem[]>(watchlist);
  const [isAdding, setIsAdding] = useState(false);
  const [newTicker, setNewTicker] = useState('');
  const [newQty, setNewQty] = useState<string>('1');
  const [newPrice, setNewPrice] = useState<string>('');
  const [isLoadingQuote, setIsLoadingQuote] = useState(false);

  // Dashboard Metrics State
  const [totalEquity, setTotalEquity] = useState(0);
  const [dayChange, setDayChange] = useState(0);
  const [totalPnL, setTotalPnL] = useState(0);

  // Simulated Historical Chart Data for Portfolio
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);

  // Effect: Fetch initial data for existing watchlist items (if any missing prices)
  useEffect(() => {
    const initData = async () => {
      const updated = await Promise.all(watchlist.map(async (item) => {
         if (!item.currentPrice) {
            const quote = await fetchStockQuote(item.ticker);
            return { ...item, currentPrice: quote.price, dayChangePercent: quote.changePercent };
         }
         return item;
      }));
      setItems(updated);
    };
    initData();
  }, [watchlist]);

  // Effect: Live Price Simulation Loop
  useEffect(() => {
    const interval = setInterval(() => {
      setItems(prevItems => prevItems.map(item => {
        if (!item.currentPrice) return item;
        const newPrice = getLivePriceUpdate(item.currentPrice);
        // Simulate day change fluctuation based on price movement
        const currentDayChange = (newPrice - (item.currentPrice / (1 + ((item.dayChangePercent || 0)/100))));
        const currentDayChangePercent = ((newPrice - (item.currentPrice - currentDayChange)) / (item.currentPrice - currentDayChange)) * 100;

        return {
            ...item,
            currentPrice: newPrice,
            dayChange: currentDayChange * item.quantity,
            dayChangePercent: currentDayChangePercent
        };
      }));
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  // Effect: Recalculate Portfolio Totals when items change
  useEffect(() => {
     let eq = 0;
     let cost = 0;
     let dChange = 0;

     items.forEach(item => {
         const price = item.currentPrice || item.avgPrice;
         const val = price * item.quantity;
         eq += val;
         cost += item.avgPrice * item.quantity;
         dChange += (item.dayChange || 0); // Mock day change logic
     });

     setTotalEquity(eq);
     setTotalPnL(eq - cost);
     setDayChange(dChange);

     // Generate chart data relative to equity to look alive
     const now = new Date();
     const points: ChartDataPoint[] = [];
     for(let i=10; i>=0; i--) {
        points.push({
            time: `${10-i}m ago`,
            value: eq * (1 - (Math.random() * 0.01 - 0.005)) // tiny noise around current equity
        });
     }
     if (points.length > 0) points[points.length-1].value = eq;
     setChartData(points);

  }, [items]);

  const handleFetchQuoteForAdd = async () => {
      if(!newTicker) return;
      setIsLoadingQuote(true);
      try {
          const quote = await fetchStockQuote(newTicker);
          setNewPrice(quote.price.toString());
      } catch (e) {
          console.error(e);
      } finally {
          setIsLoadingQuote(false);
      }
  };

  const handleAddSubmit = async () => {
    if (!newTicker || !newQty || !newPrice) return;

    // Ensure we have a valid current price
    let currentPrice = Number(newPrice);
    let dayChangePercent = 0;
    try {
        const quote = await fetchStockQuote(newTicker);
        currentPrice = quote.price; // Prefer live price if fetching new
        dayChangePercent = quote.changePercent;
    } catch(e) {
        // Fallback to user entered
    }

    addToWatchlist(newTicker.toUpperCase(), Number(newQty), Number(newPrice));

    // Local optimistic update
    setItems(prev => [...prev, {
        id: Date.now().toString(),
        ticker: newTicker.toUpperCase(),
        quantity: Number(newQty),
        avgPrice: Number(newPrice),
        currentPrice: currentPrice,
        dayChangePercent: dayChangePercent,
        dayChange: (currentPrice * (dayChangePercent/100)) * Number(newQty)
    }]);

    setIsAdding(false);
    setNewTicker('');
    setNewQty('1');
    setNewPrice('');
  };

  return (
    <div className="space-y-6">
      {/* Dashboard Header - Portfolio Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-alpha-card border border-gray-700 p-6 rounded-2xl relative overflow-hidden group">
              <div className="relative z-10">
                  <p className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-1">Net Liquidation Value</p>
                  <h2 className="text-3xl font-bold text-white">${totalEquity.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</h2>
              </div>
              <div className="absolute right-0 bottom-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                  <Icons.Briefcase size={64} className="text-blue-500" />
              </div>
          </div>

          <div className="bg-alpha-card border border-gray-700 p-6 rounded-2xl relative overflow-hidden group">
              <div className="relative z-10">
                  <p className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-1">Total P&L</p>
                  <div className={`text-3xl font-bold ${totalPnL >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                      {totalPnL >= 0 ? '+' : ''}${Math.abs(totalPnL).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                  </div>
                  <p className={`text-xs mt-1 ${totalPnL >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                      All time return
                  </p>
              </div>
               <div className="absolute right-0 bottom-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                  <Icons.Chart size={64} className={totalPnL >= 0 ? 'text-green-500' : 'text-red-500'} />
              </div>
          </div>

          <div className="bg-alpha-card border border-gray-700 p-6 rounded-2xl relative overflow-hidden group">
              <div className="relative z-10">
