import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import PortfolioCard from './components/PortfolioCard';
import WatchlistPanel from './components/WatchlistPanel';
import AdminPanel from './components/AdminPanel';
import BonusModal from './components/BonusModal';
import { View, Portfolio, WatchlistItem } from './types';
import { MOCK_PORTFOLIOS } from './services/mockData';

function App() {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [virtualBalance, setVirtualBalance] = useState(100);
  const [portfolios, setPortfolios] = useState<Portfolio[]>(MOCK_PORTFOLIOS);
  const [backedIds, setBackedIds] = useState<string[]>([]);
  const [isKOL, setIsKOL] = useState(false);
  const [streakDays, setStreakDays] = useState(0);

  // Bonus State
  const [showBonusModal, setShowBonusModal] = useState(false);
  const [bonusAmount, setBonusAmount] = useState(0);

  // Initial user watchlist
  const [watchlist, setWatchlist] = useState<WatchlistItem[]>([
      { id: '1', ticker: 'TSLA', quantity: 10, avgPrice: 165.00, currentPrice: 175.30 }
  ]);

  // DAILY LOGIN & STREAK LOGIC
  useEffect(() => {
      const checkLoginBonus = () => {
          const lastLogin = localStorage.getItem('alpha_last_login');
          const currentStreak = parseInt(localStorage.getItem('alpha_streak') || '0');
          const today = new Date().toDateString();

          if (lastLogin !== today) {
              // It's a new day
              let newStreak = 1;
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);

              if (lastLogin === yesterday.toDateString()) {
                  // Consecutive day
                  newStreak = currentStreak + 1;
              }

              // Award Bonus
              const baseBonus = 10;
              const streakBonus = Math.min(newStreak * 2, 50); // Cap streak bonus
              const totalBonus = baseBonus + streakBonus;

              setVirtualBalance(prev => prev + totalBonus);
              setStreakDays(newStreak);
              setBonusAmount(totalBonus);
              setShowBonusModal(true);

              // Persist
              localStorage.setItem('alpha_last_login', today);
              localStorage.setItem('alpha_streak', newStreak.toString());
          } else {
              // Same day login, just load stats
              setStreakDays(currentStreak);
          }
      };

      checkLoginBonus();
  }, []);

  const handleBackPortfolio = (id: string) => {
    if (virtualBalance < 10) {
      alert("Not enough virtual balance! (Cost: $10)");
      return;
    }
    setVirtualBalance(prev => prev - 10);
    setBackedIds(prev => [...prev, id]);

    // Simulate updating backer count locally
    setPortfolios(prev => prev.map(p => 
        p.id === id ? { ...p, backers: p.backers + 1 } : p
    ));
  };

  const handleAddToWatchlist = (ticker: string, quantity: number, avgPrice: number) => {
      // Logic now largely handled inside WatchlistPanel optimistic updates, 
      // but we update top-level state here to persist if we had a backend.
      const newItem: WatchlistItem = {
          id: Date.now().toString(),
          ticker,
          quantity,
          avgPrice,
          currentPrice: avgPrice // temp
      };
      setWatchlist(prev => [...prev, newItem]);
  };

  const verifyKOL = (code: string) => {
      if (code === 'ALPHA2024') {
          setIsKOL(true);
          return true;
      }
      return false;
  };

  // Render Content based on View
  const renderContent = () => {
    switch (currentView) {
      case View.HOME:
      case View.CONTESTS:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Hero Section */}
            <div className="relative rounded-2xl overflow-hidden bg-gradient-to-r from-blue-900 to-slate-900 p-6 sm:p-10 border border-blue-500/30 shadow-2xl shadow-blue-900/20">
              <div className="relative z-10 max-w-2xl">
                <span className="inline-block py-1 px-3 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-300 text-xs font-bold mb-4">
                  DAILY SHOWDOWN ACTIVE
                </span>
                <h1 className="text-3xl sm:text-4xl font-bold text-white mb-4">
                  Pick the Winners. <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-alpha-success to-alpha-accent">Keep the Alpha.</span>
                </h1>
                <p className="text-gray-300 mb-6 text-sm sm:text-base">
                  Back top KOL portfolios in 1-day sprints or long-term contests. 
                  Start with your ${virtualBalance.toFixed(0)} virtual balance.
                </p>
                <div className="flex gap-4">
                    <button onClick={() => setCurrentView(View.CONTESTS)} className="bg-white text-blue-900 font-bold px-6 py-3 rounded-xl hover:bg-gray-100 transition-colors">
                    Find a Contest
                    </button>
                    <button onClick={() => setCurrentView(View.WATCHLIST)} className="bg-blue-600/30 text-white font-bold px-6 py-3 rounded-xl hover:bg-blue-600/50 transition-colors border border-blue-400/30">
                    My Watchlist
                    </button>
                </div>
              </div>
              {/* Abstract decorative circles */}
              <div className="absolute top-0 right-0 -mt-10 -mr-10 w-64 h-64 bg-alpha-accent/20 rounded-full blur-3xl"></div>
              <div className="absolute bottom-0 left-20 w-32 h-32 bg-alpha-success/20 rounded-full blur-2xl"></div>
            </div>

            {/* Filters */}
            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                {['All', '1 Day Sprint', '1 Month', 'High Risk', 'Tech Only'].map(filter => (
                    <button key={filter} className="whitespace-nowrap px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-sm text-gray-300 hover:text-white hover:border-gray-500 transition-all">
                        {filter}
                    </button>
                ))}
            </div>

            {/* Portfolios Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {portfolios.map(portfolio => (
                <PortfolioCard 
                  key={portfolio.id} 
                  portfolio={portfolio} 
                  onBack={handleBackPortfolio}
                  isBacked={backedIds.includes(portfolio.id)}
                />
              ))}
            </div>
          </div>
        );

      case View.WATCHLIST:
        return (
            <div className="animate-in slide-in-from-bottom-4 duration-500">
                <WatchlistPanel 
                    watchlist={watchlist} 
                    addToWatchlist={handleAddToWatchlist}
                />
            </div>
        );

      case View.ADMIN:
          return (
              <AdminPanel isKOL={isKOL} onVerifyKOL={verifyKOL} />
          );

      default:
        return <div>View Not Found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-gray-100 font-sans pb-20 sm:pb-0 sm:pl-64">
      <Navbar 
        currentView={currentView} 
        setView={setCurrentView} 
        virtualBalance={virtualBalance} 
        streakDays={streakDays}
      />

      <main className="pt-20 px-4 sm:px-8 max-w-7xl mx-auto">
        {renderContent()}
      </main>

      {/* Gamification Modal */}
      {showBonusModal && (
          <BonusModal 
             bonusAmount={bonusAmount} 
             streakDays={streakDays} 
             onClose={() => setShowBonusModal(false)} 
          />
      )}
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Portfolio } from '../types';
import { Icons } from './Icons';
import { analyzePortfolioWithGemini } from '../services/geminiService';
import { AreaChart, Area, ResponsiveContainer } from 'recharts';

interface PortfolioCardProps {
  portfolio: Portfolio;
  onBack: (id: string) => void;
  isBacked: boolean;
}

const PortfolioCard: React.FC<PortfolioCardProps> = ({ portfolio, onBack, isBacked }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Generate simple sparkline data based on return
  const data = Array.from({ length: 10 }, (_, i) => ({
    val: 100 + (portfolio.totalReturn * (i / 10)) + (Math.random() * 2 - 1)
  }));

  const handleAiAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (aiAnalysis) return; // Already analyzed
    setLoadingAi(true);
    const result = await analyzePortfolioWithGemini(portfolio.stocks, portfolio.title);
    setAiAnalysis(result);
    setLoadingAi(false);
  };

  return (
    <div className="bg-alpha-card border border-gray-700 rounded-xl overflow-hidden hover:border-alpha-accent/50 transition-all duration-300 group">
      {/* Header */}
      <div className="p-4 border-b border-gray-700 flex justify-between items-start bg-gray-800/30">
        <div className="flex gap-3">
          <img src={portfolio.kolAvatar} alt={portfolio.kolName} className="w-10 h-10 rounded-full border border-gray-600" />
          <div>
            <h3 className="font-bold text-white text-sm group-hover:text-alpha-accent transition-colors">{portfolio.title}</h3>
            <div className="flex items-center gap-1 text-xs text-gray-400">
              <span>by {portfolio.kolName}</span>
              {portfolio.isVerifiedKOL && <Icons.ShieldCheck size={12} className="text-alpha-accent" />}
            </div>
          </div>
        </div>
        <div className={`px-2 py-1 rounded-md text-xs font-bold ${portfolio.totalReturn >= 0 ? 'bg-alpha-success/20 text-alpha-success' : 'bg-alpha-danger/20 text-alpha-danger'}`}>
          {portfolio.totalReturn >= 0 ? '+' : ''}{portfolio.totalReturn}%
        </div>
      </div>

      {/* Stocks Grid */}
      <div className="p-4 grid grid-cols-2 gap-2">
        {portfolio.stocks.map((stock) => (
          <div key={stock.ticker} className="bg-gray-800/50 p-2 rounded-lg flex justify-between items-center">
             <div className="flex flex-col">
               <span className="font-bold text-xs text-gray-300">{stock.ticker}</span>
               <span className="text-[10px] text-gray-500 font-mono">${stock.price.toFixed(2)}</span>
             </div>
             <span className={`text-xs font-medium ${stock.changePercent >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
               {stock.changePercent > 0 ? '+' : ''}{stock.changePercent}%
             </span>
          </div>
        ))}
      </div>

      {/* Chart preview */}
      <div className="h-16 w-full opacity-50">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data}>
            <Area 
              type="monotone" 
              dataKey="val" 
              stroke={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} 
              fill={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} 
              fillOpacity={0.1} 
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* Footer / Actions */}
      <div className="p-4 border-t border-gray-700 space-y-3">
        {/* AI Analysis Section */}
        {aiAnalysis ? (
          <div className="p-3 bg-indigo-900/20 border border-indigo-500/20 rounded-lg">
             <div className="flex items-center gap-1 text-xs text-indigo-400 mb-1">
               <Icons.Zap size={12} /> AI Analyst
             </div>
             <p className="text-xs text-gray-300 leading-relaxed">{aiAnalysis}</p>
          </div>
        ) : (
          <button 
            onClick={handleAiAnalyze}
            disabled={loadingAi}
            className="w-full py-1.5 flex items-center justify-center gap-2 text-xs font-medium text-indigo-400 hover:text-indigo-300 transition-colors"
          >
            {loadingAi ? 'Analyzing...' : <><Icons.Zap size={14} /> Reveal AI Analysis</>}
          </button>
        )}

        <div className="flex justify-between items-center pt-2">
          <div className="flex items-center gap-1 text-xs text-gray-500">
             <Icons.Users size={12} /> {portfolio.backers} Backers
          </div>
          <button 
            onClick={() => onBack(portfolio.id)}
            disabled={isBacked}
            className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${
              isBacked 
                ? 'bg-gray-700 text-gray-400 cursor-not-allowed' 
                : 'bg-alpha-success hover:bg-green-600 text-white shadow-lg shadow-green-900/20'
            }`}
          >
            {isBacked ? 'Backed' : <>Back It <Icons.TrendingUp size={16} /></>}
          </button>
        </div>
      </div>
    </div>
  );
};

