                    tickFormatter={(val) => `$${val}`}
                    axisLine={false}
                    tickLine={false}
                  />
                  <Tooltip 
                    contentStyle={{backgroundColor: '#1e293b', borderColor: '#374151', color: '#f8fafc', borderRadius: '8px'}}
