                <Icons.Users className="text-alpha-accent" />
                {portfolio.backers.toLocaleString()}
              </div>
            </div>

            {!isBacked ? (
              !isWagering ? (
                <button 
                  onClick={() => setIsWagering(true)}
                  className="w-full py-4 bg-alpha-success hover:bg-green-600 text-white font-bold rounded-xl text-lg shadow-lg shadow-green-900/30 transition-all transform hover:scale-[1.02]"
                >
                  Back This Portfolio
                </button>
              ) : (
                <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
                  <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-2 font-bold uppercase">
                      <span>Wager Amount</span>
                      <span>Balance: ${userBalance.toFixed(0)}</span>
                    </div>
                    <div className="relative">
                      <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">$</span>
                      <input 
                        type="number" 
                        value={wagerAmount}
                        onChange={(e) => setWagerAmount(e.target.value)}
                        className="w-full bg-black/40 border border-gray-600 rounded-xl pl-8 pr-4 py-3 text-white font-bold focus:border-alpha-success focus:outline-none"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <button 
                      onClick={() => setIsWagering(false)}
                      className="py-3 bg-gray-700 hover:bg-gray-600 text-gray-300 font-bold rounded-xl"
