import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import PortfolioCard from './components/PortfolioCard';
import PortfolioDetailView from './components/PortfolioDetailView';
import WatchlistPanel from './components/WatchlistPanel';
import AdminPanel from './components/AdminPanel';
import BonusModal from './components/BonusModal';
import { View, Portfolio, WatchlistItem } from './types';
import { MOCK_PORTFOLIOS } from './services/mockData';

function App() {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [virtualBalance, setVirtualBalance] = useState(100);
  const [portfolios, setPortfolios] = useState<Portfolio[]>(MOCK_PORTFOLIOS);
  const [backedIds, setBackedIds] = useState<string[]>([]);
  const [isKOL, setIsKOL] = useState(false);
  const [streakDays, setStreakDays] = useState(0);
  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);

  // Bonus State
  const [showBonusModal, setShowBonusModal] = useState(false);
  const [bonusAmount, setBonusAmount] = useState(0);

  // Initial user watchlist
  const [watchlist, setWatchlist] = useState<WatchlistItem[]>([
      { id: '1', ticker: 'TSLA', quantity: 10, avgPrice: 165.00, currentPrice: 175.30 }
  ]);

  // DAILY LOGIN & STREAK LOGIC
  useEffect(() => {
      const checkLoginBonus = () => {
          const lastLogin = localStorage.getItem('alpha_last_login');
          const currentStreak = parseInt(localStorage.getItem('alpha_streak') || '0');
          const today = new Date().toDateString();

          if (lastLogin !== today) {
              // It's a new day
              let newStreak = 1;
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);

              if (lastLogin === yesterday.toDateString()) {
                  // Consecutive day
                  newStreak = currentStreak + 1;
              }

              // Award Bonus
              const baseBonus = 10;
              const streakBonus = Math.min(newStreak * 2, 50); // Cap streak bonus
              const totalBonus = baseBonus + streakBonus;

              setVirtualBalance(prev => prev + totalBonus);
              setStreakDays(newStreak);
              setBonusAmount(totalBonus);
              setShowBonusModal(true);

              // Persist
              localStorage.setItem('alpha_last_login', today);
              localStorage.setItem('alpha_streak', newStreak.toString());
          } else {
              // Same day login, just load stats
              setStreakDays(currentStreak);
          }
      };

      checkLoginBonus();
  }, []);

  const handleBackPortfolio = (id: string, amount: number) => {
    if (virtualBalance < amount) {
      alert("Not enough virtual balance!");
      return;
    }
    setVirtualBalance(prev => prev - amount);
    setBackedIds(prev => [...prev, id]);

    // Simulate updating backer count locally
    setPortfolios(prev => prev.map(p => 
        p.id === id ? { ...p, backers: p.backers + 1 } : p
    ));
  };

  const handleAddToWatchlist = (ticker: string, quantity: number, avgPrice: number) => {
      // Logic now largely handled inside WatchlistPanel optimistic updates, 
      // but we update top-level state here to persist if we had a backend.
      const newItem: WatchlistItem = {
          id: Date.now().toString(),
          ticker,
          quantity,
          avgPrice,
          currentPrice: avgPrice // temp
      };
      setWatchlist(prev => [...prev, newItem]);
  };

  const verifyKOL = (code: string) => {
      if (code === 'ALPHA2024') {
          setIsKOL(true);
          return true;
      }
      return false;
  };

  const handleViewPortfolio = (portfolio: Portfolio) => {
    setSelectedPortfolio(portfolio);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReturnFromDetail = () => {
    setSelectedPortfolio(null);
  };

  // Ensure navigation resets detail view
  const handleNavChange = (view: View) => {
    setCurrentView(view);
    setSelectedPortfolio(null);
  };

  // Render Content based on View
  const renderContent = () => {
    if (selectedPortfolio) {
      return (
        <PortfolioDetailView 
          portfolio={selectedPortfolio}
          onBack={handleReturnFromDetail}
          onWager={handleBackPortfolio}
          userBalance={virtualBalance}
          isBacked={backedIds.includes(selectedPortfolio.id)}
        />
      );
    }

    switch (currentView) {
      case View.HOME:
      case View.CONTESTS:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Hero Section */}
            <div className="relative rounded-2xl overflow-hidden bg-gradient-to-r from-blue-900 to-slate-900 p-6 sm:p-10 border border-blue-500/30 shadow-2xl shadow-blue-900/20">
              <div className="relative z-10 max-w-2xl">
                <span className="inline-block py-1 px-3 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-300 text-xs font-bold mb-4">
                  DAILY SHOWDOWN ACTIVE
                </span>
                <h1 className="text-3xl sm:text-4xl font-bold text-white mb-4">
                  Pick the Winners. <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-alpha-success to-alpha-accent">Keep the Alpha.</span>
                </h1>
                <p className="text-gray-300 mb-6 text-sm sm:text-base">
                  Back top KOL portfolios in 1-day sprints or long-term contests. 
                  Start with your ${virtualBalance.toFixed(0)} virtual balance.
                </p>
                <div className="flex gap-4">
                    <button onClick={() => setCurrentView(View.CONTESTS)} className="bg-white text-blue-900 font-bold px-6 py-3 rounded-xl hover:bg-gray-100 transition-colors">
                    Find a Contest
                    </button>
                    <button onClick={() => setCurrentView(View.WATCHLIST)} className="bg-blue-600/30 text-white font-bold px-6 py-3 rounded-xl hover:bg-blue-600/50 transition-colors border border-blue-400/30">
                    My Watchlist
                    </button>
                </div>
              </div>
              {/* Abstract decorative circles */}
              <div className="absolute top-0 right-0 -mt-10 -mr-10 w-64 h-64 bg-alpha-accent/20 rounded-full blur-3xl"></div>
              <div className="absolute bottom-0 left-20 w-32 h-32 bg-alpha-success/20 rounded-full blur-2xl"></div>
            </div>

            {/* Filters */}
            <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
                {['All', '1 Day Sprint', '1 Month', 'High Risk', 'Tech Only'].map(filter => (
                    <button key={filter} className="whitespace-nowrap px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-sm text-gray-300 hover:text-white hover:border-gray-500 transition-all">
                        {filter}
                    </button>
                ))}
            </div>

            {/* Portfolios Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {portfolios.map(portfolio => (
                <PortfolioCard 
                  key={portfolio.id} 
                  portfolio={portfolio} 
                  onBack={handleBackPortfolio}
                  isBacked={backedIds.includes(portfolio.id)}
                  userBalance={virtualBalance}
                  onView={handleViewPortfolio}
                />
              ))}
            </div>
          </div>
        );

      case View.WATCHLIST:
        return (
            <div className="animate-in slide-in-from-bottom-4 duration-500">
                <WatchlistPanel 
                    watchlist={watchlist} 
                    addToWatchlist={handleAddToWatchlist}
                />
            </div>
        );

      case View.ADMIN:
          return (
              <AdminPanel isKOL={isKOL} onVerifyKOL={verifyKOL} />
          );

      default:
        return <div>View Not Found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-gray-100 font-sans pb-20 sm:pb-0 sm:pl-64">
      <Navbar 
        currentView={currentView} 
        setView={handleNavChange} 
        virtualBalance={virtualBalance} 
        streakDays={streakDays}
      />

      <main className="pt-20 px-4 sm:px-8 max-w-7xl mx-auto">
        {renderContent()}
      </main>

      {/* Gamification Modal */}
      {showBonusModal && (
          <BonusModal 
             bonusAmount={bonusAmount} 
             streakDays={streakDays} 
             onClose={() => setShowBonusModal(false)} 
          />
      )}
    </div>
  );
}

export default App;

import { GoogleGenAI } from "@google/genai";
import { Stock } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize client only if key exists to avoid runtime crashes in demo without key
const getAiClient = () => {
  if (!API_KEY) return null;
  return new GoogleGenAI({ apiKey: API_KEY });
};

export const analyzePortfolioWithGemini = async (stocks: Stock[], strategyName: string): Promise<string> => {
  const ai = getAiClient();
  if (!ai) {
    return "Gemini API Key is missing. Please configure your environment to enable AI analysis.";
  }

  const stockList = stocks.map(s => s.ticker).join(', ');
  const prompt = `
    You are a senior financial analyst for a fintech app called Alpha Seeker.
    Analyze this 4-stock portfolio: ${stockList}.
    The strategy name is "${strategyName}".

    Provide a concise (max 3 sentences) energetic analysis of why this portfolio might succeed or fail in the current market environment. 
    Focus on sector exposure and volatility.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text || "Analysis unavailable.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "AI Analysis temporarily unavailable due to network or API limits.";
  }
};

export const generateStockNewsDigest = async (stocks: Stock[]): Promise<string> => {
  const ai = getAiClient();
  if (!ai) {
    return "Gemini API Key is missing. Please configure your environment to enable AI analysis.";
  }

  const stockList = stocks.map(s => s.ticker).join(', ');
  const prompt = `
    You are a financial news reporter for Alpha Seeker.
    For each of the following stocks: ${stockList}.

    Provide a concise, 1-sentence news digest highlight for each stock based on recent real-world events or general market sentiment typical for these companies.

    Format exactly like this for each stock (do not use markdown bolding):
    [TICKER]: [News Summary]
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });
    return response.text || "News digest unavailable.";
  } catch (error) {
    console.error("Gemini Digest Error:", error);
    return "AI News Digest temporarily unavailable.";
  }
};

export const generateMarketSentiment = async (): Promise<{sentiment: string, score: number}> => {
   // Simulated for demo robustness, but structure ready for real API
   // In a real scenario, this would digest news headlines.
   return {
       sentiment: "Bullish on Tech, Cautious on Consumer Discretionary",
       score: 75 // 0-100
   }
}

import React, { useState, useEffect } from 'react';
import { Portfolio, ChartDataPoint } from '../types';
import { Icons } from './Icons';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { generateHistoricalData } from '../services/stockData';
import { generateStockNewsDigest } from '../services/geminiService';

interface PortfolioDetailViewProps {
  portfolio: Portfolio;
  onBack: () => void;
  onWager: (id: string, amount: number) => void;
  userBalance: number;
  isBacked: boolean;
}

const PortfolioDetailView: React.FC<PortfolioDetailViewProps> = ({ portfolio, onBack, onWager, userBalance, isBacked }) => {
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);
  const [timeRange, setTimeRange] = useState<'1D' | '1W' | '1M' | 'ALL'>('1M');
  const [wagerAmount, setWagerAmount] = useState('10');
  const [isWagering, setIsWagering] = useState(false);
  const [digest, setDigest] = useState<string | null>(null);
  const [loadingDigest, setLoadingDigest] = useState(false);

  useEffect(() => {
    // Simulate fetching historical data based on the portfolio's return
    // We base the curve on the portfolio's current "totalReturn" to make it look consistent
    const points = timeRange === '1D' ? 24 : timeRange === '1W' ? 7 : 30;
    const baseValue = 1000;
    const data = generateHistoricalData(baseValue * (1 + portfolio.totalReturn / 100), points);
    setChartData(data);
  }, [portfolio, timeRange]);

  const handleWagerConfirm = () => {
    const amount = Number(wagerAmount);
    if (amount > 0 && amount <= userBalance) {
      onWager(portfolio.id, amount);
      setIsWagering(false);
    }
  };

  const handleGenerateDigest = async () => {
    setLoadingDigest(true);
    const result = await generateStockNewsDigest(portfolio.stocks);
    setDigest(result);
    setLoadingDigest(false);
  };

  return (
    <div className="animate-in slide-in-from-right-4 duration-300">
      {/* Navigation Header */}
      <button 
        onClick={onBack} 
        className="flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors group"
      >
        <div className="p-1 rounded-full bg-gray-800 group-hover:bg-gray-700">
             <Icons.TrendingDown className="rotate-90" size={16} /> {/* Using rotated arrow as back icon substitute */}
        </div>
        <span className="font-bold text-sm">Back to Contest List</span>
      </button>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Main Chart & Info */}
        <div className="lg:col-span-2 space-y-6">

          {/* Header Card */}
          <div className="bg-alpha-card border border-gray-700 rounded-2xl p-6">
            <div className="flex justify-between items-start mb-6">
              <div className="flex gap-4">
                <img src={portfolio.kolAvatar} alt={portfolio.kolName} className="w-16 h-16 rounded-full border-2 border-alpha-accent" />
                <div>
                  <h1 className="text-2xl font-bold text-white mb-1">{portfolio.title}</h1>
                  <div className="flex items-center gap-2 text-sm text-gray-400">
                    <span className="font-medium text-white">{portfolio.kolName}</span>
                    {portfolio.isVerifiedKOL && <Icons.ShieldCheck size={14} className="text-alpha-accent" />}
                    <span className="w-1 h-1 bg-gray-600 rounded-full"></span>
                    <span>{portfolio.expiry} Horizon</span>
                  </div>
                </div>
              </div>
              <div className="text-right">
                <div className={`text-3xl font-bold ${portfolio.totalReturn >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                  {portfolio.totalReturn >= 0 ? '+' : ''}{portfolio.totalReturn}%
                </div>
                <div className="text-xs text-gray-400">Total Return</div>
              </div>
            </div>

            {/* Main Chart */}
            <div className="h-80 w-full mb-6">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="colorPnL" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} stopOpacity={0.3}/>
                      <stop offset="95%" stopColor={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#374151" vertical={false} />
                  <XAxis dataKey="time" hide />
                  <YAxis 
                    domain={['auto', 'auto']} 
                    orientation="right" 
                    tick={{fill: '#9ca3af', fontSize: 12}}
                    tickFormatter={(val) => `$${val}`}
                    axisLine={false}
                    tickLine={false}
                  />
                  <Tooltip 
                    contentStyle={{backgroundColor: '#1e293b', borderColor: '#374151', color: '#f8fafc', borderRadius: '8px'}}
                    itemStyle={{color: '#fff'}}
                    formatter={(value: number) => [`$${value.toFixed(2)}`, 'Portfolio Value']}
                  />
                  <Area 
                    type="monotone" 
                    dataKey="value" 
                    stroke={portfolio.totalReturn >= 0 ? '#10b981' : '#ef4444'} 
                    fillOpacity={1} 
                    fill="url(#colorPnL)" 
                    strokeWidth={3}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>

            {/* Time Range Selectors */}
            <div className="flex gap-2">
              {['1D', '1W', '1M', 'ALL'].map((range) => (
                <button
                  key={range}
                  onClick={() => setTimeRange(range as any)}
                  className={`px-4 py-1 rounded-lg text-sm font-bold transition-all ${
                    timeRange === range 
                      ? 'bg-gray-700 text-white' 
                      : 'bg-transparent text-gray-500 hover:text-gray-300'
                  }`}
                >
                  {range}
                </button>
              ))}
            </div>
          </div>

          {/* AI News Digest Section */}
          <div className="bg-alpha-card border border-gray-700 rounded-2xl p-6 relative overflow-hidden">
             {/* Background decoration */}
             <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

             <div className="flex items-center gap-2 mb-4 relative z-10">
                <div className="p-2 bg-indigo-500/20 rounded-lg">
                    <Icons.Zap className="text-indigo-400" size={20} />
                </div>
                <div>
                    <h3 className="font-bold text-white">AI News Digest</h3>
                    <p className="text-xs text-gray-400">Powered by Gemini 2.5</p>
                </div>
             </div>

             {!digest ? (
                <div className="text-center py-6 relative z-10">
                    <p className="text-gray-400 text-sm mb-4">Get real-time news summaries for the stocks in this portfolio.</p>
                    <button 
                        onClick={handleGenerateDigest}
                        disabled={loadingDigest}
                        className="bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-2 px-6 rounded-lg transition-colors flex items-center gap-2 mx-auto disabled:opacity-50"
                    >
                        {loadingDigest ? 'Generating...' : <><Icons.Zap size={16} /> Generate Digest</>}
                    </button>
                </div>
             ) : (
                <div className="space-y-3 animate-in fade-in relative z-10">
                    {digest.split('\n').filter(line => line.trim().length > 0).map((line, i) => {
                        const parts = line.split(':');
                        const ticker = parts[0]?.trim();
                        const content = parts.slice(1).join(':').trim();

                        // Check if line actually matches Ticker: Content format, otherwise just display line
                        if (content && ticker.length < 8) {
                             return (
                                <div key={i} className="p-3 bg-gray-800/50 rounded-lg border border-gray-700/50 hover:border-indigo-500/30 transition-colors">
                                    <div className="flex items-start gap-2">
                                        <span className="text-alpha-accent font-bold text-sm min-w-[60px]">{ticker}</span>
                                        <p className="text-sm text-gray-300 leading-snug">{content}</p>
                                    </div>
                                </div>
                             );
                        }
                        return (
                             <div key={i} className="p-3 bg-gray-800/50 rounded-lg border border-gray-700/50">
                                <p className="text-sm text-gray-300">{line}</p>
                            </div>
                        );
                    })}
                </div>
             )}
          </div>

          {/* Holdings Breakdown */}
          <div className="bg-alpha-card border border-gray-700 rounded-2xl p-6">
            <h3 className="font-bold text-white mb-4 flex items-center gap-2">
              <Icons.Briefcase size={18} className="text-alpha-gold" /> Holdings Breakdown
            </h3>
            <div className="space-y-3">
              {portfolio.stocks.map((stock) => (
                <div key={stock.ticker} className="flex items-center justify-between p-3 bg-gray-800/50 rounded-xl hover:bg-gray-800 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-gray-700 flex items-center justify-center font-bold text-gray-300 text-xs">
                      {stock.ticker[0]}
                    </div>
                    <div>
                      <div className="font-bold text-white">{stock.ticker}</div>
                      <div className="text-xs text-gray-400">{stock.name}</div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="font-mono text-white">${stock.price.toFixed(2)}</div>
                    <div className={`text-xs font-bold ${stock.changePercent >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                      {stock.changePercent > 0 ? '+' : ''}{stock.changePercent}%
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Right Column: Actions & Stats */}
        <div className="space-y-6">

          {/* Action Card */}
          <div className="bg-gradient-to-b from-gray-800 to-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl">
            <div className="text-center mb-6">
              <p className="text-gray-400 text-sm mb-1">Current Backers</p>
              <div className="text-3xl font-bold text-white flex items-center justify-center gap-2">
                <Icons.Users className="text-alpha-accent" />
                {portfolio.backers.toLocaleString()}
              </div>
            </div>

            {!isBacked ? (
              !isWagering ? (
                <button 
                  onClick={() => setIsWagering(true)}
                  className="w-full py-4 bg-alpha-success hover:bg-green-600 text-white font-bold rounded-xl text-lg shadow-lg shadow-green-900/30 transition-all transform hover:scale-[1.02]"
                >
                  Back This Portfolio
                </button>
              ) : (
                <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
                  <div>
                    <div className="flex justify-between text-xs text-gray-400 mb-2 font-bold uppercase">
                      <span>Wager Amount</span>
                      <span>Balance: ${userBalance.toFixed(0)}</span>
                    </div>
                    <div className="relative">
                      <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">$</span>
                      <input 
                        type="number" 
                        value={wagerAmount}
                        onChange={(e) => setWagerAmount(e.target.value)}
                        className="w-full bg-black/40 border border-gray-600 rounded-xl pl-8 pr-4 py-3 text-white font-bold focus:border-alpha-success focus:outline-none"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <button 
                      onClick={() => setIsWagering(false)}
                      className="py-3 bg-gray-700 hover:bg-gray-600 text-gray-300 font-bold rounded-xl"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={handleWagerConfirm}
                      disabled={Number(wagerAmount) <= 0 || Number(wagerAmount) > userBalance}
                      className="py-3 bg-alpha-success hover:bg-green-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl"
                    >
                      Confirm
                    </button>
                  </div>
                </div>
              )
            ) : (
              <div className="bg-green-900/30 border border-green-500/30 rounded-xl p-4 text-center">
                <div className="flex justify-center mb-2">
                  <div className="p-2 bg-green-500 rounded-full text-white">
                    <Icons.ShieldCheck size={24} />
                  </div>
                </div>
                <h3 className="text-green-400 font-bold mb-1">Portfolio Backed!</h3>
                <p className="text-xs text-gray-400">You are tracking this strategy.</p>
              </div>
            )}
          </div>

          {/* Strategy Description */}
          <div className="bg-alpha-card border border-gray-700 rounded-2xl p-6">
            <h3 className="font-bold text-white mb-3 text-sm uppercase tracking-wider text-gray-500">About Strategy</h3>
            <p className="text-gray-300 leading-relaxed text-sm">
              {portfolio.description}
            </p>
            <div className="mt-4 pt-4 border-t border-gray-700 flex flex-wrap gap-2">
              <span className="px-3 py-1 bg-blue-900/30 border border-blue-500/30 text-blue-400 text-xs rounded-full font-bold">Tech Sector</span>
              <span className="px-3 py-1 bg-purple-900/30 border border-purple-500/30 text-purple-400 text-xs rounded-full font-bold">High Growth</span>
              <span className="px-3 py-1 bg-orange-900/30 border border-orange-500/30 text-orange-400 text-xs rounded-full font-bold">Volatility</span>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
};

