import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import PortfolioCard from './components/PortfolioCard';
import PortfolioDetailView from './components/PortfolioDetailView';
import WatchlistPanel from './components/WatchlistPanel';
import AdminPanel from './components/AdminPanel';
import BonusModal from './components/BonusModal';
import { View, Portfolio, WatchlistItem } from './types';
import { MOCK_PORTFOLIOS } from './services/mockData';
import { Icons } from './components/Icons';

// Mock Contest Definitions
const CONTEST_TYPES = [
  { 
    id: 'daily', 
    title: 'Daily Sprint', 
    prize: '1,000', 
    expiry: '1 Day', 
    entry: 'Free',
    color: 'from-orange-500 to-red-600',
    icon: <Icons.Zap size={24} className="text-white" />,
    description: 'Fast-paced action. Highest intraday gainer wins.'
  },
  { 
    id: 'monthly', 
    title: 'Monthly Marathon', 
    prize: '5,000', 
    expiry: '1 Month', 
    entry: '$10',
    color: 'from-blue-600 to-indigo-600',
    icon: <Icons.Trophy size={24} className="text-white" />,
    description: 'Strategy pays off. Best 30-day performance.'
  },
  { 
    id: 'yearly', 
    title: 'Legends League', 
    prize: '50,000', 
    expiry: '1 Year', 
    entry: '$100',
    color: 'from-purple-600 to-fuchsia-600',
    icon: <Icons.Crown size={24} className="text-white" />,
    description: 'For the long-term visionaries. High stakes.'
  },
];

function App() {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [virtualBalance, setVirtualBalance] = useState(100);
  const [portfolios, setPortfolios] = useState<Portfolio[]>(MOCK_PORTFOLIOS);
  const [backedIds, setBackedIds] = useState<string[]>([]);
  const [isKOL, setIsKOL] = useState(false);
  const [streakDays, setStreakDays] = useState(0);
  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);

  // Contest Filtering State
  const [selectedContestFilter, setSelectedContestFilter] = useState<string>('All');

  // Bonus State
  const [showBonusModal, setShowBonusModal] = useState(false);
  const [bonusAmount, setBonusAmount] = useState(0);

  // Initial user watchlist
  const [watchlist, setWatchlist] = useState<WatchlistItem[]>([
      { id: '1', ticker: 'TSLA', quantity: 10, avgPrice: 165.00, currentPrice: 175.30 }
  ]);

  // DAILY LOGIN & STREAK LOGIC
  useEffect(() => {
      const checkLoginBonus = () => {
          const lastLogin = localStorage.getItem('alpha_last_login');
          const currentStreak = parseInt(localStorage.getItem('alpha_streak') || '0');
          const today = new Date().toDateString();

          if (lastLogin !== today) {
              // It's a new day
              let newStreak = 1;
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);

              if (lastLogin === yesterday.toDateString()) {
                  // Consecutive day
                  newStreak = currentStreak + 1;
              }

              // Award Bonus
              const baseBonus = 10;
              const streakBonus = Math.min(newStreak * 2, 50); // Cap streak bonus
              const totalBonus = baseBonus + streakBonus;

              setVirtualBalance(prev => prev + totalBonus);
              setStreakDays(newStreak);
              setBonusAmount(totalBonus);
              setShowBonusModal(true);

              // Persist
              localStorage.setItem('alpha_last_login', today);
              localStorage.setItem('alpha_streak', newStreak.toString());
          } else {
              // Same day login, just load stats
              setStreakDays(currentStreak);
          }
      };

      checkLoginBonus();
  }, []);

  const handleBackPortfolio = (id: string, amount: number) => {
    if (virtualBalance < amount) {
      alert("Not enough virtual balance!");
      return;
    }
    setVirtualBalance(prev => prev - amount);
    setBackedIds(prev => [...prev, id]);

    // Simulate updating backer count locally
    setPortfolios(prev => prev.map(p => 
        p.id === id ? { ...p, backers: p.backers + 1 } : p
    ));
  };

  const handleAddToWatchlist = (ticker: string, quantity: number, avgPrice: number) => {
      // Logic now largely handled inside WatchlistPanel optimistic updates, 
      // but we update top-level state here to persist if we had a backend.
      const newItem: WatchlistItem = {
          id: Date.now().toString(),
          ticker,
          quantity,
          avgPrice,
          currentPrice: avgPrice // temp
      };
      setWatchlist(prev => [...prev, newItem]);
  };

  const verifyKOL = (code: string) => {
      if (code === 'ALPHA2024') {
          setIsKOL(true);
          return true;
      }
      return false;
  };

  const handleViewPortfolio = (portfolio: Portfolio) => {
    setSelectedPortfolio(portfolio);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleReturnFromDetail = () => {
    setSelectedPortfolio(null);
  };

  // Ensure navigation resets detail view
  const handleNavChange = (view: View) => {
    setCurrentView(view);
    setSelectedPortfolio(null);
    setSelectedContestFilter('All'); // Reset filters when changing views
  };

  const handleContestSelect = (expiryFilter: string) => {
    setSelectedContestFilter(expiryFilter);
  };

  // Filter logic
  const getFilteredPortfolios = () => {
    if (currentView === View.CONTESTS && selectedContestFilter !== 'All') {
       return portfolios.filter(p => p.expiry === selectedContestFilter);
    }
    return portfolios;
  };

  const filteredPortfolios = getFilteredPortfolios();

  // Render Content based on View
  const renderContent = () => {
    if (selectedPortfolio) {
      return (
        <PortfolioDetailView 
          portfolio={selectedPortfolio}
          onBack={handleReturnFromDetail}
          onWager={handleBackPortfolio}
          userBalance={virtualBalance}
          isBacked={backedIds.includes(selectedPortfolio.id)}
        />
      );
    }

    switch (currentView) {
      case View.HOME:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Hero Section */}
            <div className="relative rounded-2xl overflow-hidden bg-gradient-to-r from-blue-900 to-slate-900 p-6 sm:p-10 border border-blue-500/30 shadow-2xl shadow-blue-900/20">
              <div className="relative z-10 max-w-2xl">
                <span className="inline-block py-1 px-3 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-300 text-xs font-bold mb-4">
                  DAILY SHOWDOWN ACTIVE
                </span>
                <h1 className="text-3xl sm:text-4xl font-bold text-white mb-4">
                  Pick the Winners. <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-alpha-success to-alpha-accent">Keep the Alpha.</span>
                </h1>
                <p className="text-gray-300 mb-6 text-sm sm:text-base">
                  Back top KOL portfolios in 1-day sprints or long-term contests. 
                  Start with your ${virtualBalance.toFixed(0)} virtual balance.
                </p>
                <div className="flex gap-4">
                    <button onClick={() => handleNavChange(View.CONTESTS)} className="bg-white text-blue-900 font-bold px-6 py-3 rounded-xl hover:bg-gray-100 transition-colors">
                    Find a Contest
                    </button>
                    <button onClick={() => handleNavChange(View.WATCHLIST)} className="bg-blue-600/30 text-white font-bold px-6 py-3 rounded-xl hover:bg-blue-600/50 transition-colors border border-blue-400/30">
                    My Watchlist
                    </button>
                </div>
              </div>
              {/* Abstract decorative circles */}
              <div className="absolute top-0 right-0 -mt-10 -mr-10 w-64 h-64 bg-alpha-accent/20 rounded-full blur-3xl"></div>
              <div className="absolute bottom-0 left-20 w-32 h-32 bg-alpha-success/20 rounded-full blur-2xl"></div>
            </div>

            {/* Trending Section Header */}
            <div className="flex items-center gap-2 mb-2">
                <Icons.Flame className="text-orange-500" />
                <h2 className="text-xl font-bold text-white">Trending Portfolios</h2>
            </div>

            {/* Portfolios Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {portfolios.slice(0, 3).map(portfolio => (
                <PortfolioCard 
                  key={portfolio.id} 
                  portfolio={portfolio} 
                  onBack={handleBackPortfolio}
                  isBacked={backedIds.includes(portfolio.id)}
                  userBalance={virtualBalance}
                  onView={handleViewPortfolio}
                />
              ))}
            </div>

             <div className="text-center">
                 <button onClick={() => handleNavChange(View.CONTESTS)} className="text-gray-400 hover:text-white text-sm font-medium">View All Contests &rarr;</button>
             </div>
          </div>
        );

      case View.CONTESTS:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="flex justify-between items-center">
                 <div>
                    <h1 className="text-3xl font-bold text-white">Contest Lobby</h1>
                    <p className="text-gray-400">Select a competition to view eligible portfolios</p>
                 </div>
                 <div className="hidden sm:block">
                     <div className="bg-gray-800 rounded-lg p-1 flex">
                         <button className="px-3 py-1 bg-gray-700 rounded-md text-xs font-bold text-white">Featured</button>
                         <button className="px-3 py-1 hover:bg-gray-700 rounded-md text-xs text-gray-400">Private</button>
                     </div>
                 </div>
             </div>

             {/* Contest Type Cards */}
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                 {CONTEST_TYPES.map(contest => (
                     <div 
                        key={contest.id}
                        onClick={() => handleContestSelect(contest.expiry)}
                        className={`relative cursor-pointer group rounded-xl p-5 border transition-all duration-300 ${
                            selectedContestFilter === contest.expiry 
                                ? 'bg-gray-800 border-alpha-accent ring-1 ring-alpha-accent' 
                                : 'bg-gray-800/50 border-gray-700 hover:border-gray-500'
                        }`}
                     >
                         <div className={`absolute top-0 right-0 w-24 h-24 bg-gradient-to-br ${contest.color} opacity-10 rounded-full blur-2xl -mr-10 -mt-10 group-hover:opacity-20 transition-opacity`}></div>

                         <div className="flex items-start justify-between mb-4">
                             <div className={`p-3 rounded-xl bg-gradient-to-br ${contest.color} shadow-lg shadow-black/40`}>
                                 {contest.icon}
                             </div>
                             {selectedContestFilter === contest.expiry && (
                                 <div className="px-2 py-1 bg-alpha-accent/20 text-alpha-accent text-[10px] font-bold uppercase rounded border border-alpha-accent/30">Selected</div>
                             )}
                         </div>

                         <h3 className="text-lg font-bold text-white mb-1">{contest.title}</h3>
                         <p className="text-xs text-gray-400 mb-4 h-8">{contest.description}</p>

                         <div className="flex justify-between items-center pt-3 border-t border-gray-700/50">
                             <div className="flex flex-col">
                                 <span className="text-[10px] uppercase text-gray-500 font-bold">Prize Pool</span>
                                 <span className="text-sm font-bold text-alpha-gold">${contest.prize}</span>
                             </div>
                             <div className="flex flex-col items-end">
                                 <span className="text-[10px] uppercase text-gray-500 font-bold">Expiry</span>
                                 <div className="flex items-center gap-1 text-sm font-bold text-white">
                                     <Icons.Clock size={12} /> {contest.expiry}
                                 </div>
                             </div>
                         </div>
                     </div>
                 ))}
             </div>

             {/* Filtered Portfolios */}
             <div>
                 <div className="flex items-center gap-2 mb-4">
                     <Icons.Briefcase className="text-gray-400" size={20}/>
                     <h3 className="text-lg font-bold text-white">
                         {selectedContestFilter === 'All' ? 'All Portfolios' : `Portfolios for ${selectedContestFilter} Contest`}
                     </h3>
                     <span className="text-sm text-gray-500 bg-gray-800 px-2 py-0.5 rounded-full">
                         {filteredPortfolios.length}
                     </span>
                 </div>

                 {filteredPortfolios.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4">
                        {filteredPortfolios.map(portfolio => (
                            <PortfolioCard 
                            key={portfolio.id} 
                            portfolio={portfolio} 
                            onBack={handleBackPortfolio}
                            isBacked={backedIds.includes(portfolio.id)}
                            userBalance={virtualBalance}
                            onView={handleViewPortfolio}
                            />
                        ))}
                    </div>
                 ) : (
                     <div className="text-center py-12 bg-gray-800/30 rounded-xl border border-gray-700 border-dashed">
                         <div className="w-16 h-16 bg-gray-800 rounded-full flex items-center justify-center mx-auto mb-4">
                             <Icons.Briefcase className="text-gray-500" size={32} />
                         </div>
                         <h3 className="text-white font-bold mb-1">No Portfolios Found</h3>
                         <p className="text-gray-500 text-sm">No active strategies match the {selectedContestFilter} criteria.</p>
                         <button 
                            onClick={() => setSelectedContestFilter('All')} 
                            className="mt-4 text-alpha-accent hover:text-blue-400 text-sm font-bold"
                         >
                             Clear Filters
                         </button>
                     </div>
                 )}
             </div>
          </div>
        );

      case View.WATCHLIST:
        return (
            <div className="animate-in slide-in-from-bottom-4 duration-500">
                <WatchlistPanel 
                    watchlist={watchlist} 
                    addToWatchlist={handleAddToWatchlist}
                />
            </div>
        );

      case View.ADMIN:
          return (
              <AdminPanel isKOL={isKOL} onVerifyKOL={verifyKOL} />
          );

      default:
        return <div>View Not Found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-gray-100 font-sans pb-20 sm:pb-0 sm:pl-64">
      <Navbar 
        currentView={currentView} 
        setView={handleNavChange} 
        virtualBalance={virtualBalance} 
        streakDays={streakDays}
      />

      <main className="pt-20 px-4 sm:px-8 max-w-7xl mx-auto">
        {renderContent()}
      </main>

      {/* Gamification Modal */}
      {showBonusModal && (
          <BonusModal 
             bonusAmount={bonusAmount} 
             streakDays={streakDays} 
             onClose={() => setShowBonusModal(false)} 
          />
      )}
    </div>
  );
}

