import { GoogleGenAI } from "@google/genai";
import { Stock } from '../types';
import { MOCK_STOCKS } from './mockData';

const API_KEY = process.env.API_KEY || '';

// Mock helpers for fallback
const getRandomPrice = (min: number, max: number) => Number((Math.random() * (max - min) + min).toFixed(2));
const getRandomChange = () => Number((Math.random() * 6 - 3).toFixed(2));

// Simple in-memory cache to prevent excessive API calls during a session
const SESSION_CACHE: Record<string, Stock> = {};

/**
 * Fetches stock data.
 * Tries to use Gemini with Google Search Grounding to get real-time data from Google Finance/Knowledge Graph.
 * Falls back to mock data if API key is missing or request fails.
 */
export const fetchStockQuote = async (ticker: string): Promise<Stock> => {
  const upperTicker = ticker.toUpperCase();

  // 1. Check Cache
  if (SESSION_CACHE[upperTicker]) {
    return { ...SESSION_CACHE[upperTicker] };
  }

  // 2. Try Gemini (Real Data)
  if (API_KEY) {
    try {
      const ai = new GoogleGenAI({ apiKey: API_KEY });
      // We ask for JSON format in the prompt. 
      // Note: We cannot use 'responseMimeType: application/json' combined with tools: googleSearch.
      const prompt = `
        Search for the current stock price and daily percentage change for ${upperTicker} (${upperTicker} stock).

        Return a JSON object with these keys:
        - price: number (current price)
        - changePercent: number (daily % change, e.g. -1.5 or 2.3)
        - name: string (company name)

        Example: {"price": 150.20, "changePercent": 0.5, "name": "Example Corp"}
        Return ONLY the JSON.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        }
      });

      const text = response.text || '';

      // Extract JSON from potential Markdown blocks
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const jsonStr = jsonMatch[0];
        const data = JSON.parse(jsonStr);

        // Basic Validation
        if (data.price !== undefined) {
           const realStock: Stock = {
             ticker: upperTicker,
             name: data.name || `${upperTicker} Corp`,
             price: Number(data.price),
             changePercent: Number(data.changePercent || 0),
             sector: 'Unknown'
           };

           SESSION_CACHE[upperTicker] = realStock;
           return realStock;
        }
      }
    } catch (error) {
      console.warn(`Gemini stock fetch failed for ${upperTicker}, falling back to mock.`, error);
    }
  }

  // 3. Fallback to Mock Data

  // Check if we have a hardcoded mock for consistency
  const existing = MOCK_STOCKS.find(s => s.ticker === upperTicker);
  if (existing) {
     return { ...existing };
  }

  // Generate random plausible data
  const mockStock: Stock = {
    ticker: upperTicker,
    name: `${upperTicker} Corp`,
    price: getRandomPrice(20, 450),
    changePercent: getRandomChange(),
    sector: 'Unknown'
  };

  SESSION_CACHE[upperTicker] = mockStock;
  return mockStock;
};

// Simulation helper for live ticking effect
export const getLivePriceUpdate = (currentPrice: number): number => {
  const volatility = 0.002; // 0.2% max volatility per tick
  const drift = (Math.random() - 0.5) * 2; // -1 to 1
  const change = currentPrice * volatility * drift;
  return Number((currentPrice + change).toFixed(2));
};

export const generateHistoricalData = (basePrice: number, points: number = 30) => {
  const data = [];
  let current = basePrice * 0.90; // Start lower to show "growth" usually
  for (let i = 0; i < points; i++) {
    current = getLivePriceUpdate(current);
    data.push({
      time: `Day ${i + 1}`,
      value: current
    });
  }
  // Force the last point to align somewhat with current price
  data[data.length - 1].value = basePrice;
  return data;
};

import React, { useState, useEffect } from 'react';
import { Portfolio, ChartDataPoint, Stock } from '../types';
import { Icons } from './Icons';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { generateHistoricalData, fetchStockQuote } from '../services/stockData';
import { generateStockNewsDigest } from '../services/geminiService';

interface PortfolioDetailViewProps {
  portfolio: Portfolio;
  onBack: () => void;
  onWager: (id: string, amount: number) => void;
  userBalance: number;
  isBacked: boolean;
}

const PortfolioDetailView: React.FC<PortfolioDetailViewProps> = ({ portfolio, onBack, onWager, userBalance, isBacked }) => {
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);
  const [timeRange, setTimeRange] = useState<'1D' | '1W' | '1M' | 'ALL'>('1M');
  const [wagerAmount, setWagerAmount] = useState('10');
  const [isWagering, setIsWagering] = useState(false);
  const [digest, setDigest] = useState<string | null>(null);
  const [loadingDigest, setLoadingDigest] = useState(false);

  // Local state for stocks to allow live updating
  const [currentStocks, setCurrentStocks] = useState<Stock[]>(portfolio.stocks);
  const [isRefreshing, setIsRefreshing] = useState(false);

  useEffect(() => {
    // Simulate fetching historical data based on the portfolio's return
    const points = timeRange === '1D' ? 24 : timeRange === '1W' ? 7 : 30;
    const baseValue = 1000;
    const data = generateHistoricalData(baseValue * (1 + portfolio.totalReturn / 100), points);
    setChartData(data);
  }, [portfolio, timeRange]);

  const handleWagerConfirm = () => {
    const amount = Number(wagerAmount);
    if (amount > 0 && amount <= userBalance) {
      onWager(portfolio.id, amount);
      setIsWagering(false);
    }
  };

  const handleGenerateDigest = async () => {
    setLoadingDigest(true);
    const result = await generateStockNewsDigest(currentStocks);
    setDigest(result);
    setLoadingDigest(false);
  };

  const handleRefreshPrices = async () => {
      setIsRefreshing(true);
      try {
          const updatedStocks = await Promise.all(
              currentStocks.map(async (stock) => {
                  try {
                      // Fetch fresh data
                      const fresh = await fetchStockQuote(stock.ticker);
                      return fresh;
                  } catch (e) {
                      return stock;
                  }
              })
          );
          setCurrentStocks(updatedStocks);
