import React, { useState, useEffect } from 'react';
import { WatchlistItem, ChartDataPoint, Stock } from '../types';
import { Icons } from './Icons';
import { fetchStockQuote, getLivePriceUpdate } from '../services/stockData';
import { AreaChart, Area, ResponsiveContainer, XAxis, YAxis, Tooltip } from 'recharts';

interface WatchlistPanelProps {
  watchlist: WatchlistItem[];
  addToWatchlist: (ticker: string, qty: number, avgPrice: number) => void;
}

const WatchlistPanel: React.FC<WatchlistPanelProps> = ({ watchlist, addToWatchlist }) => {
  const [items, setItems] = useState<WatchlistItem[]>(watchlist);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResult, setSearchResult] = useState<Stock | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');

  // Add Form State
  const [isAddingResult, setIsAddingResult] = useState(false);
  const [addQty, setAddQty] = useState('1');

  // Dashboard Metrics State
  const [totalEquity, setTotalEquity] = useState(0);
  const [dayChange, setDayChange] = useState(0);
  const [totalPnL, setTotalPnL] = useState(0);

  // Simulated Historical Chart Data for Portfolio
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);

  // Effect: Fetch initial data for existing watchlist items
  useEffect(() => {
    const initData = async () => {
      const updated = await Promise.all(watchlist.map(async (item) => {
         if (!item.currentPrice) {
            const quote = await fetchStockQuote(item.ticker);
            return { ...item, currentPrice: quote.price, dayChangePercent: quote.changePercent };
         }
         return item;
      }));
      setItems(updated);
    };
    initData();
  }, [watchlist]);

  // Effect: Live Price Simulation Loop
  useEffect(() => {
    const interval = setInterval(() => {
      setItems(prevItems => prevItems.map(item => {
        if (!item.currentPrice) return item;
        const newPrice = getLivePriceUpdate(item.currentPrice);
        const costBasis = item.currentPrice / (1 + ((item.dayChangePercent || 0)/100));
        const currentDayChange = (newPrice - costBasis);
        const currentDayChangePercent = ((newPrice - costBasis) / costBasis) * 100;

        return {
            ...item,
            currentPrice: newPrice,
            dayChange: currentDayChange * item.quantity,
            dayChangePercent: currentDayChangePercent
        };
      }));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // Effect: Recalculate Portfolio Totals
  useEffect(() => {
     let eq = 0;
     let cost = 0;
     let dChange = 0;

     items.forEach(item => {
         const price = item.currentPrice || item.avgPrice;
         const val = price * item.quantity;
         eq += val;
         cost += item.avgPrice * item.quantity;
         dChange += (item.dayChange || 0);
     });

     setTotalEquity(eq);
     setTotalPnL(eq - cost);
     setDayChange(dChange);

     const points: ChartDataPoint[] = [...chartData];
     if (points.length > 20) points.shift();
     points.push({
         time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
         value: eq
     });
     setChartData(points);

  }, [items]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery) return;

    setIsSearching(true);
    setSearchError('');
    setSearchResult(null);
    setIsAddingResult(false);

    try {
      const quote = await fetchStockQuote(searchQuery);
      if (quote) {
        setSearchResult(quote);
      } else {
        setSearchError('Stock not found');
      }
    } catch (err) {
      setSearchError('Search failed. Try again.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleConfirmAdd = () => {
    if (!searchResult) return;

    const qty = Number(addQty);
    if (qty <= 0) return;

    addToWatchlist(searchResult.ticker, qty, searchResult.price);

    // Local optimistic update
    setItems(prev => [...prev, {
        id: Date.now().toString(),
        ticker: searchResult.ticker,
        quantity: qty,
        avgPrice: searchResult.price,
        currentPrice: searchResult.price,
        dayChangePercent: searchResult.changePercent,
        dayChange: (searchResult.price * (searchResult.changePercent/100)) * qty
    }]);

    // Reset Search
    setSearchResult(null);
    setSearchQuery('');
    setIsAddingResult(false);
    setAddQty('1');
  };

  return (
    <div className="space-y-6">
      {/* Search Header Section */}
      <div className="bg-alpha-card border border-gray-700 rounded-2xl p-6 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-alpha-accent/5 rounded-full blur-3xl -mr-32 -mt-32 pointer-events-none"></div>

        <div className="relative z-10">
          <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
            <Icons.Search className="text-alpha-accent" size={20} />
            Search & Discovery
          </h2>

          <form onSubmit={handleSearch} className="flex gap-2">
            <div className="relative flex-1">
              <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
              <input 
                type="text" 
                placeholder="Search ticker or company (e.g. AAPL, NVIDIA, Tesla)..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-gray-900/50 border border-gray-600 rounded-xl pl-10 pr-4 py-3 text-white focus:outline-none focus:border-alpha-accent focus:ring-1 focus:ring-alpha-accent/50 transition-all"
              />
            </div>
            <button 
              type="submit"
              disabled={isSearching}
              className="bg-alpha-accent hover:bg-blue-600 text-white px-6 py-3 rounded-xl font-bold transition-all flex items-center gap-2 disabled:opacity-50"
            >
              {isSearching ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : 'Search'}
            </button>
          </form>

          {/* Search Results Preview */}
          {searchResult && (
            <div className="mt-4 p-4 bg-gray-800/80 border border-alpha-accent/30 rounded-xl animate-in fade-in slide-in-from-top-2">
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-alpha-accent/20 rounded-xl flex items-center justify-center font-bold text-alpha-accent text-lg">
                    {searchResult.ticker[0]}
                  </div>
                  <div>
                    <h3 className="font-bold text-white text-lg">{searchResult.ticker}</h3>
                    <p className="text-sm text-gray-400">{searchResult.name}</p>
                  </div>
                  <div className="px-4 border-l border-gray-700">
                    <p className="text-xl font-mono text-white font-bold">${searchResult.price.toFixed(2)}</p>
                    <p className={`text-sm font-bold ${searchResult.changePercent >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                      {searchResult.changePercent > 0 ? '+' : ''}{searchResult.changePercent.toFixed(2)}%
                    </p>
                  </div>
                </div>

                {!isAddingResult ? (
                  <button 
                    onClick={() => setIsAddingResult(true)}
                    className="w-full sm:w-auto px-6 py-2 bg-alpha-success hover:bg-green-600 text-white font-bold rounded-lg transition-colors flex items-center justify-center gap-2"
                  >
                    <Icons.Plus size={18} /> Add to Watchlist
                  </button>
                ) : (
                  <div className="flex items-center gap-2 w-full sm:w-auto">
                    <div className="flex-1 sm:w-24">
                      <label className="text-[10px] text-gray-500 uppercase font-bold block mb-1">Quantity</label>
                      <input 
                        type="number" 
                        value={addQty}
                        onChange={(e) => setAddQty(e.target.value)}
                        className="w-full bg-gray-900 border border-gray-600 rounded-lg px-3 py-1.5 text-white text-sm focus:outline-none"
                      />
                    </div>
                    <button 
                      onClick={handleConfirmAdd}
                      className="mt-5 px-4 py-1.5 bg-alpha-success text-white font-bold rounded-lg text-sm"
                    >
                      Confirm
                    </button>
                    <button 
                      onClick={() => setIsAddingResult(false)}
                      className="mt-5 px-4 py-1.5 bg-gray-700 text-gray-400 font-bold rounded-lg text-sm"
                    >
                      X
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
          {searchError && (
            <div className="mt-4 p-3 bg-red-900/20 border border-red-500/20 rounded-xl text-red-400 text-sm flex items-center gap-2">
              <Icons.ShieldCheck size={16} /> {searchError}
            </div>
          )}
        </div>
      </div>

      {/* Dashboard Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-alpha-card border border-gray-700 p-6 rounded-2xl relative overflow-hidden group">
              <div className="relative z-10">
                  <p className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-1">Watchlist Equity</p>
                  <h2 className="text-3xl font-bold text-white">${totalEquity.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</h2>
              </div>
              <div className="absolute right-0 bottom-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                  <Icons.Briefcase size={64} className="text-blue-500" />
              </div>
          </div>

