import { GoogleGenAI } from "@google/genai";
import { Stock } from '../types';
import { MOCK_STOCKS } from './mockData';

const API_KEY = process.env.API_KEY || '';

export interface StockQuoteResponse {
  stock: Stock;
  sources: { title: string; uri: string }[];
}

// Simple in-memory cache to prevent excessive API calls during a session
const SESSION_CACHE: Record<string, StockQuoteResponse> = {};

/**
 * Fetches real-time stock data using Gemini with Google Search Grounding.
 */
export const fetchStockQuote = async (ticker: string): Promise<StockQuoteResponse> => {
  const upperTicker = ticker.toUpperCase();

  if (SESSION_CACHE[upperTicker]) {
    return SESSION_CACHE[upperTicker];
  }

  if (API_KEY) {
    try {
      const ai = new GoogleGenAI({ apiKey: API_KEY });
      const prompt = `
        Fetch the CURRENT real-time stock price and daily percentage change for "${upperTicker}" stock.

        Return exactly this JSON structure:
        {
          "price": number,
          "changePercent": number,
          "name": "Full Company Name"
        }

        Ensure the price is the latest available market price.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
        }
      });

      const text = response.text || '';
      const jsonMatch = text.match(/\{[\s\S]*\}/);

      // Extract sources for compliance
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({
          title: chunk.web.title,
          uri: chunk.web.uri
        }));

      if (jsonMatch) {
        const data = JSON.parse(jsonMatch[0]);
        if (data.price !== undefined) {
           const res: StockQuoteResponse = {
             stock: {
               ticker: upperTicker,
               name: data.name || `${upperTicker} Corp`,
               price: Number(data.price),
               changePercent: Number(data.changePercent || 0),
               sector: 'Market'
             },
             sources: sources.slice(0, 3) // Keep top 3 sources
           };
           SESSION_CACHE[upperTicker] = res;
           return res;
        }
      }
    } catch (error) {
      console.warn(`Gemini search failed for ${upperTicker}, using mock data.`, error);
    }
  }

  // Fallback to Mock Data if no API key or failure
  const existing = MOCK_STOCKS.find(s => s.ticker === upperTicker);
  const fallbackStock = existing || {
    ticker: upperTicker,
    name: `${upperTicker} Corp`,
    price: 150.00,
    changePercent: 0.00,
    sector: 'Unknown'
  };

  return { stock: fallbackStock, sources: [] };
};

export const getLivePriceUpdate = (currentPrice: number): number => {
  const volatility = 0.0005; // Extremely low for "live" feel without being fake
  const change = currentPrice * volatility * (Math.random() - 0.5);
  return Number((currentPrice + change).toFixed(2));
};

export const generateHistoricalData = (basePrice: number, points: number = 30) => {
  const data = [];
  let current = basePrice * 0.95;
  for (let i = 0; i < points; i++) {
    const volatility = 0.01;
    current = current * (1 + (Math.random() * volatility - volatility/2));
    data.push({
      time: `T-${points-i}`,
      value: Number(current.toFixed(2))
    });
  }
  data[data.length - 1].value = basePrice;
  return data;
};

