import { GoogleGenAI } from "@google/genai";
import { Stock } from '../types';
import { MOCK_STOCKS } from './mockData';

export interface StockQuoteResponse {
  stock: Stock;
  sources: { title: string; uri: string }[];
}

// Simple in-memory cache to prevent excessive API calls during a short window
const SESSION_CACHE: Record<string, { data: StockQuoteResponse, timestamp: number }> = {};
const CACHE_TTL = 60000; // 1 minute cache

/**
 * Fetches real-time stock data using Gemini with Google Search Grounding.
 * Targets reliable sources like Google Finance or Yahoo Finance.
 */
export const fetchStockQuote = async (ticker: string): Promise<StockQuoteResponse> => {
  const upperTicker = ticker.toUpperCase();
  const now = Date.now();

  if (SESSION_CACHE[upperTicker] && (now - SESSION_CACHE[upperTicker].timestamp < CACHE_TTL)) {
    return SESSION_CACHE[upperTicker].data;
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    // Using gemini-3-flash-preview for fast search-grounded queries
    const prompt = `
      Retrieve the current real-time stock price and today's percentage change for ticker "${upperTicker}" from Google Finance.
      Provide the result in a clean JSON format:
      {
        "price": 0.00,
        "changePercent": 0.00,
        "companyName": "string"
      }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    const text = response.text || '';
    // Extract JSON from text response
    const jsonMatch = text.match(/\{[\s\S]*\}/);

    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .filter((chunk: any) => chunk.web)
      .map((chunk: any) => ({
        title: chunk.web.title,
        uri: chunk.web.uri
      }));

    if (jsonMatch) {
      try {
        const cleanedJson = jsonMatch[0].replace(/```json|```/g, '').trim();
        const data = JSON.parse(cleanedJson);

        if (data.price !== undefined) {
           const res: StockQuoteResponse = {
             stock: {
               ticker: upperTicker,
               name: data.companyName || `${upperTicker} Corp`,
               price: Number(data.price),
               changePercent: Number(data.changePercent || 0),
               sector: 'Market'
             },
             sources: sources.slice(0, 3)
           };
           SESSION_CACHE[upperTicker] = { data: res, timestamp: now };
           return res;
        }
      } catch (e) {
        console.error("Failed to parse Gemini stock response", e);
      }
    }
  } catch (error) {
    console.warn(`Real-time search failed for ${upperTicker}, using mock fallback.`, error);
  }

  // Fallback to mock data if real-time fetch fails
  const existing = MOCK_STOCKS.find(s => s.ticker === upperTicker);
  const fallbackStock = existing || {
    ticker: upperTicker,
    name: `${upperTicker} Corp`,
    price: 100.00,
    changePercent: 0.00,
    sector: 'Unknown'
  };

  return { stock: fallbackStock, sources: [] };
};

/**
 * Returns a small random fluctuation to simulate "live" ticking in the UI 
 * between actual API refreshes.
 */
export const getLivePriceUpdate = (currentPrice: number): number => {
  const volatility = 0.0005; // 0.05%
  const change = currentPrice * volatility * (Math.random() - 0.5);
  return Number((currentPrice + change).toFixed(2));
};

export const generateHistoricalData = (basePrice: number, points: number = 30) => {
  const data = [];
  let current = basePrice * 0.98;
  for (let i = 0; i < points; i++) {
    const volatility = 0.015;
    current = current * (1 + (Math.random() * volatility - volatility/2));
    data.push({
      time: `T-${points-i}`,
      value: Number(current.toFixed(2))
    });
  }
  data[data.length - 1].value = basePrice;
  return data;
};

