  };

  /**
   * Orchestrates the fetching of real-time data for all active tickers.
   * Updates state across portfolios and watchlists.
   */
  const syncMarketData = async () => {
    if (isSyncingPrices) return;

    // Identify all unique tickers currently in view or tracked
    const tickers = new Set<string>();
    watchlist.forEach(item => tickers.add(item.ticker));
    portfolios.forEach(p => p.stocks.forEach(s => tickers.add(s.ticker)));

    setIsSyncingPrices(true);
    const tickerArray = Array.from(tickers);

    try {
      const quotesMap: Record<string, any> = {};

      // Fetch in sequence to respect potential grounding rate limits
      for (const ticker of tickerArray) {
        const res = await fetchStockQuote(ticker);
        quotesMap[ticker] = res.stock;
      }

      // Update global portfolios state
      setPortfolios(prev => prev.map(p => {
        const updatedStocks = p.stocks.map(s => quotesMap[s.ticker] || s);
        // Calculate new total return based on updated stock prices
        // (Simplified logic: average of individual stock % changes for demo)
        const avgReturn = updatedStocks.reduce((sum, s) => sum + s.changePercent, 0) / updatedStocks.length;
        return { ...p, stocks: updatedStocks, totalReturn: Number(avgReturn.toFixed(2)) };
      }));

      // Update global watchlist state
      setWatchlist(prev => prev.map(item => {
        const quote = quotesMap[item.ticker];
        if (quote) {
          return {
            ...item,
            currentPrice: quote.price,
            dayChangePercent: quote.changePercent
          };
        }
        return item;
      }));

      setLastSyncTime(new Date());
    } catch (err) {
      console.error("Critical error during market sync:", err);
    } finally {
      setIsSyncingPrices(false);
    }
  };

  // Sync on mount
  useEffect(() => {
    syncMarketData();
  }, []);

  // Periodic Refresh (every 120 seconds to be safe with rate limits)
  useEffect(() => {
    const interval = setInterval(() => {
      syncMarketData();
    }, 120000);
    return () => clearInterval(interval);
  }, [watchlist, portfolios]);

  useEffect(() => {
      const checkLoginBonus = () => {
          const lastLogin = localStorage.getItem('alpha_last_login');
          const currentStreak = parseInt(localStorage.getItem('alpha_streak') || '0');
          const today = new Date().toDateString();

          if (lastLogin !== today) {
              let newStreak = 1;
              const yesterday = new Date();
              yesterday.setDate(yesterday.getDate() - 1);

              if (lastLogin === yesterday.toDateString()) {
                  newStreak = currentStreak + 1;
              }

              const baseBonus = 10;
              const streakBonus = Math.min(newStreak * 2, 50);
              const totalBonus = baseBonus + streakBonus;

              setVirtualBalance(prev => prev + totalBonus);
              setStreakDays(newStreak);
              setBonusAmount(totalBonus);
              setShowBonusModal(true);

              localStorage.setItem('alpha_last_login', today);
              localStorage.setItem('alpha_streak', newStreak.toString());
          } else {
              setStreakDays(currentStreak);
          }
      };

      checkLoginBonus();
  }, []);

  const handleBackPortfolio = (id: string, amount: number) => {
    if (virtualBalance < amount) {
      addToast("Insufficient virtual balance!", "error");
      return;
    }
    setVirtualBalance(prev => prev - amount);
    setBackedIds(prev => [...prev, id]);

    setPortfolios(prev => prev.map(p => 
        p.id === id ? { ...p, backers: p.backers + 1 } : p
    ));
    addToast(`Successfully backed portfolio with $${amount}!`, "success");
  };

  const handleAddToWatchlist = (ticker: string, quantity: number, avgPrice: number) => {
      const newItem: WatchlistItem = {
          id: Date.now().toString(),
          ticker: ticker.toUpperCase(),
          quantity,
          avgPrice,
          currentPrice: avgPrice
      };
      setWatchlist(prev => [...prev, newItem]);
      addToast(`${ticker.toUpperCase()} added to your watchlist.`, "success");
      // Trigger sync for the new ticker
      syncMarketData();
  };

  const verifyKOL = (code: string) => {
      if (code === 'ALPHA2024') {
          setIsKOL(true);
          addToast("KOL Status Verified!", "success");
          return true;
      }
      return false;
  };

  const handleViewPortfolio = (portfolio: Portfolio) => {
    setSelectedPortfolio(portfolio);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleViewGameRoom = (room: GameRoom) => {
      setSelectedGameRoom(room);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavChange = (view: View) => {
    setCurrentView(view);
    setSelectedPortfolio(null);
    setSelectedGameRoom(null);
    setSelectedContestFilter('All');
    setSearchQuery('');
  };

  const filteredPortfolios = (currentView === View.CONTESTS && selectedContestFilter !== 'All') 
    ? portfolios.filter(p => p.expiry === selectedContestFilter)
    : searchQuery && searchType === 'PORTFOLIOS'
      ? portfolios.filter(p => 
          p.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
          p.kolName.toLowerCase().includes(searchQuery.toLowerCase()) ||
          p.stocks.some(s => s.ticker.includes(searchQuery.toUpperCase()))
        )
      : portfolios;

  const filteredGameRooms = searchQuery && searchType === 'ROOMS'
    ? gameRooms.filter(r => 
        r.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        r.description.toLowerCase().includes(searchQuery.toLowerCase())
      )
    : gameRooms;

  const renderContent = () => {
    if (selectedPortfolio) {
      return (
        <PortfolioDetailView 
          portfolio={selectedPortfolio}
          onBack={() => setSelectedPortfolio(null)}
          onWager={handleBackPortfolio}
          userBalance={virtualBalance}
          isBacked={backedIds.includes(selectedPortfolio.id)}
        />
      );
    }

    if (selectedGameRoom) {
        return (
            <GameRoomDetailView 
                room={selectedGameRoom}
                portfolios={portfolios}
                onBack={() => setSelectedGameRoom(null)}
                onJoin={(id) => addToast("Join request sent!", "info")}
                onViewPortfolio={handleViewPortfolio}
                onBackPortfolio={handleBackPortfolio}
                userBalance={virtualBalance}
                backedIds={backedIds}
            />
        );
    }

    switch (currentView) {
      case View.HOME:
        return (
          <div className="space-y-8 animate-in fade-in duration-700 slide-in-from-bottom-2">
            <div className="relative rounded-2xl overflow-hidden glass p-6 sm:p-10 border-blue-500/30 shadow-2xl">
              <div className="relative z-10 max-w-2xl">
                <span className="inline-block py-1 px-3 rounded-full bg-blue-500/20 border border-blue-400/30 text-blue-300 text-xs font-bold mb-4">
                  BETA ACCESS V1.0
                </span>
                <h1 className="text-3xl sm:text-5xl font-bold text-white mb-4 leading-tight">
                  Track. Compete. <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-alpha-success to-alpha-accent">Real-Time Markets.</span>
                </h1>

                <div className="w-full max-w-lg mt-8 bg-black/40 p-2 rounded-2xl border border-gray-600 backdrop-blur-xl">
                   <div className="relative flex items-center mb-2">
                       <Icons.Search className="absolute left-3 text-gray-400" size={20} />
                       <input 
                          type="text" 
                          placeholder={searchType === 'PORTFOLIOS' ? "Search portfolios, tickers, KOLs..." : "Search game rooms & private groups..."}
                          value={searchQuery}
                          onChange={(e) => setSearchQuery(e.target.value)}
                          className="w-full bg-transparent border-none text-white pl-10 pr-4 py-3 focus:outline-none placeholder-gray-500 font-medium"
                       />
                   </div>
                   <div className="flex gap-2">
                       <button 
                         onClick={() => setSearchType('PORTFOLIOS')}
                         className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${searchType === 'PORTFOLIOS' ? 'bg-alpha-accent text-white shadow-lg' : 'bg-transparent text-gray-400 hover:text-white'}`}
                       >
                           Public Portfolios
                       </button>
                       <button 
                         onClick={() => setSearchType('ROOMS')}
                         className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${searchType === 'ROOMS' ? 'bg-alpha-accent text-white shadow-lg' : 'bg-transparent text-gray-400 hover:text-white'}`}
                       >
                           Game Rooms
                       </button>
                   </div>
                </div>
              </div>
              <div className="absolute top-0 right-0 -mt-20 -mr-20 w-80 h-80 bg-alpha-accent/10 rounded-full blur-[100px] animate-pulse-slow"></div>
              <div className="absolute bottom-0 left-20 w-48 h-48 bg-alpha-success/10 rounded-full blur-[80px]"></div>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        {searchQuery ? <Icons.Search className="text-alpha-accent" /> : <Icons.Flame className="text-orange-500 animate-pulse" />}
                        <h2 className="text-xl font-bold text-white flex items-center gap-2">
                            {searchType === 'PORTFOLIOS' ? (searchQuery ? 'Portfolio Results' : 'Trending Portfolios') : (searchQuery ? 'Game Room Results' : 'Active Game Rooms')}
                            {isSyncingPrices && <span className="text-xs font-normal text-alpha-accent animate-pulse flex items-center gap-1"><Icons.Clock size={12}/> Syncing real-time prices...</span>}
                        </h2>
                    </div>
                    {lastSyncTime && !isSyncingPrices && (
                        <div className="text-[10px] text-gray-500 flex items-center gap-1">
                            <Icons.Clock size={10} /> Last Sync: {lastSyncTime.toLocaleTimeString()}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {searchType === 'PORTFOLIOS' ? 
                        filteredPortfolios.map(p => <PortfolioCard key={p.id} portfolio={p} onBack={handleBackPortfolio} isBacked={backedIds.includes(p.id)} userBalance={virtualBalance} onView={handleViewPortfolio} />) :
                        filteredGameRooms.map(r => <GameRoomCard key={r.id} room={r} onJoin={() => addToast("Join request sent!", "info")} onView={handleViewGameRoom} />)
                    }
                    {((searchType === 'PORTFOLIOS' && filteredPortfolios.length === 0) || (searchType === 'ROOMS' && filteredGameRooms.length === 0)) && (
                        <div className="col-span-full text-center py-20 text-gray-500 border border-gray-800 border-dashed rounded-2xl bg-gray-900/20">
                            No results found for "{searchQuery}"
                        </div>
                    )}
                </div>
            </div>
          </div>
        );

      case View.CONTESTS:
        return (
            <div className="space-y-8 animate-in fade-in duration-500">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                    <div>
                        <h1 className="text-3xl font-bold text-white">Contest Lobby</h1>
                        <p className="text-gray-400">Battle it out with top-tier strategies.</p>
                    </div>
                    <div className="bg-gray-800 rounded-xl p-1 flex border border-gray-700">
                         <button className="px-4 py-2 bg-gray-700 rounded-lg text-xs font-bold text-white shadow-md">Public</button>
                         <button className="px-4 py-2 hover:bg-gray-700 rounded-lg text-xs font-bold text-gray-400">Private Leagues</button>
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {CONTEST_TYPES.map(c => (
                        <div key={c.id} onClick={() => setSelectedContestFilter(c.expiry)} className={`relative cursor-pointer group rounded-2xl p-6 border transition-all duration-300 ${selectedContestFilter === c.expiry ? 'bg-gray-800 border-alpha-accent ring-2 ring-alpha-accent/20' : 'bg-alpha-card border-gray-700 hover:border-gray-500'}`}>
                            <div className={`p-4 rounded-2xl bg-gradient-to-br ${c.color} shadow-lg mb-6 w-fit animate-float`}>{c.icon}</div>
                            <h3 className="text-xl font-bold text-white mb-2">{c.title}</h3>
                            <p className="text-sm text-gray-400 mb-6">{c.description}</p>
                            <div className="flex justify-between items-center pt-4 border-t border-gray-700">
                                <span className="text-alpha-gold font-bold text-lg">${c.prize}</span>
                                <span className="text-xs font-bold text-gray-500 bg-gray-900 px-3 py-1 rounded-full">{c.expiry}</span>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {filteredPortfolios.map(p => <PortfolioCard key={p.id} portfolio={p} onBack={handleBackPortfolio} isBacked={backedIds.includes(p.id)} userBalance={virtualBalance} onView={handleViewPortfolio} />)}
                </div>
            </div>
        );

      case View.WATCHLIST:
        return <WatchlistPanel watchlist={watchlist} addToWatchlist={handleAddToWatchlist} />;

      case View.ADMIN:
        return <AdminPanel isKOL={isKOL} onVerifyKOL={verifyKOL} />;

      default:
        return <div className="text-center py-20 text-gray-500">View Not Found</div>;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-gray-100 font-sans pb-20 sm:pb-0 sm:pl-64">
      <Navbar currentView={currentView} setView={handleNavChange} virtualBalance={virtualBalance} streakDays={streakDays} />
      <main className="pt-24 px-4 sm:px-8 max-w-7xl mx-auto pb-10">{renderContent()}</main>
      {showBonusModal && <BonusModal bonusAmount={bonusAmount} streakDays={streakDays} onClose={() => setShowBonusModal(false)} />}

      {/* Toast Notifications */}
      <div className="fixed bottom-20 sm:bottom-6 right-6 z-[100] flex flex-col gap-2">
          {toasts.map(t => (
              <div key={t.id} className={`flex items-center gap-3 px-5 py-3 rounded-xl shadow-2xl animate-in slide-in-from-right-10 glass border-l-4 ${t.type === 'success' ? 'border-alpha-success' : t.type === 'error' ? 'border-alpha-danger' : 'border-alpha-accent'}`}>
                  {t.type === 'success' ? <Icons.ShieldCheck className="text-alpha-success" size={20} /> : <Icons.Zap size={20} className="text-alpha-accent" />}
                  <span className="text-sm font-bold">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { WatchlistItem, ChartDataPoint, Stock } from '../types';
import { Icons } from './Icons';
import { fetchStockQuote, getLivePriceUpdate } from '../services/stockData';
import { AreaChart, Area, ResponsiveContainer, XAxis, YAxis, Tooltip } from 'recharts';

interface WatchlistPanelProps {
  watchlist: WatchlistItem[];
  addToWatchlist: (ticker: string, qty: number, avgPrice: number) => void;
}

const WatchlistPanel: React.FC<WatchlistPanelProps> = ({ watchlist, addToWatchlist }) => {
  const [items, setItems] = useState<WatchlistItem[]>(watchlist);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResult, setSearchResult] = useState<Stock | null>(null);
  const [searchSources, setSearchSources] = useState<{title: string, uri: string}[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');

  // Add Form State
  const [isAddingResult, setIsAddingResult] = useState(false);
  const [addQty, setAddQty] = useState('1');

  // Dashboard Metrics
  const [totalEquity, setTotalEquity] = useState(0);
  const [totalPnL, setTotalPnL] = useState(0);
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);

  // Update local items when global watchlist changes
  useEffect(() => {
    setItems(watchlist);
  }, [watchlist]);

  // Visual "Tick" effect between real refreshes
  useEffect(() => {
    const interval = setInterval(() => {
      setItems(prevItems => prevItems.map(item => {
        if (!item.currentPrice) return item;
        const newPrice = getLivePriceUpdate(item.currentPrice);
        return { ...item, currentPrice: newPrice };
      }));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
     let eq = 0;
     let cost = 0;
     items.forEach(item => {
         const price = item.currentPrice || item.avgPrice;
         eq += price * item.quantity;
         cost += item.avgPrice * item.quantity;
     });
     setTotalEquity(eq);
     setTotalPnL(eq - cost);

     setChartData(prev => {
        const next = [...prev, { time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second:'2-digit'}), value: eq }];
        return next.slice(-30);
     });
  }, [items]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery) return;
    setIsSearching(true);
    setSearchError('');
    setSearchResult(null);
    try {
      const res = await fetchStockQuote(searchQuery);
      if (res.stock) {
        setSearchResult(res.stock);
        setSearchSources(res.sources);
      } else {
        setSearchError('Stock not found');
      }
    } catch (err) {
      setSearchError('Search failed.');
    } finally {
      setIsSearching(false);
    }
  };

  const handleConfirmAdd = () => {
    if (!searchResult) return;
    addToWatchlist(searchResult.ticker, Number(addQty), searchResult.price);
    setSearchResult(null);
    setSearchQuery('');
    setIsAddingResult(false);
  };

  return (
    <div className="space-y-6">
      <div className="bg-alpha-card border border-gray-700 rounded-2xl p-6 shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
            <Icons.Search className="text-alpha-accent" size={20} />
            Live Market Search
          </h2>
          <form onSubmit={handleSearch} className="flex gap-2">
            <input 
              type="text" 
              placeholder="Enter ticker (e.g. AAPL, NVDA)..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="flex-1 bg-gray-900 border border-gray-600 rounded-xl px-4 py-3 text-white focus:border-alpha-accent outline-none"
            />
            <button type="submit" disabled={isSearching} className="bg-alpha-accent hover:bg-blue-600 text-white px-6 py-3 rounded-xl font-bold transition-all disabled:opacity-50">
              {isSearching ? 'Fetching Real Data...' : 'Get Live Price'}
            </button>
          </form>

          {searchError && <p className="text-alpha-danger text-xs mt-2 font-bold">{searchError}</p>}

          {searchResult && (
            <div className="mt-4 p-4 bg-gray-800/80 border border-alpha-accent/30 rounded-xl animate-in fade-in slide-in-from-top-2">
              <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-alpha-accent/20 rounded-xl flex items-center justify-center font-bold text-alpha-accent text-lg">
                    {searchResult.ticker[0]}
                  </div>
                  <div>
                    <h3 className="font-bold text-white text-lg">{searchResult.ticker}</h3>
                    <p className="text-sm text-gray-400">{searchResult.name}</p>
                  </div>
                  <div className="px-4 border-l border-gray-700">
                    <p className="text-xl font-mono text-white font-bold">${searchResult.price.toFixed(2)}</p>
                    <p className={`text-sm font-bold ${searchResult.changePercent >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                      {searchResult.changePercent > 0 ? '+' : ''}{searchResult.changePercent.toFixed(2)}%
                    </p>
                  </div>
                </div>
                {!isAddingResult ? (
                  <button onClick={() => setIsAddingResult(true)} className="px-6 py-2 bg-alpha-success hover:bg-green-600 text-white font-bold rounded-lg flex items-center gap-2">
                    <Icons.Plus size={18} /> Add to Watchlist
                  </button>
                ) : (
                  <div className="flex items-center gap-2">
                    <input type="number" value={addQty} onChange={(e) => setAddQty(e.target.value)} className="w-20 bg-gray-900 border border-gray-600 rounded-lg px-3 py-1.5 text-white" />
                    <button onClick={handleConfirmAdd} className="px-4 py-1.5 bg-alpha-success text-white font-bold rounded-lg">Confirm</button>
                    <button onClick={() => setIsAddingResult(false)} className="px-4 py-1.5 bg-gray-700 text-gray-400 font-bold rounded-lg">X</button>
                  </div>
                )}
              </div>
              {searchSources.length > 0 && (
                <div className="mt-3 flex gap-2 overflow-x-auto pb-1">
                    <span className="text-[10px] text-gray-500 font-bold self-center uppercase mr-1">Sources:</span>
                    {searchSources.map((s, i) => (
                        <a key={i} href={s.uri} target="_blank" rel="noopener" className="text-[10px] text-alpha-accent whitespace-nowrap bg-black/30 px-2 py-1 rounded hover:bg-alpha-accent/20 transition-colors">
                            {s.title}
                        </a>
                    ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="bg-alpha-card border border-gray-700 p-6 rounded-2xl relative overflow-hidden">
              <div className="relative z-10">
                <p className="text-gray-400 text-xs font-bold uppercase mb-1">Total Equity (Market)</p>
                <h2 className="text-3xl font-bold text-white font-mono">${totalEquity.toLocaleString(undefined, {minimumFractionDigits: 2})}</h2>
              </div>
              <div className="absolute right-0 bottom-0 w-32 h-20 opacity-20">
                <ResponsiveContainer width="100%" height="100%">
                   <AreaChart data={chartData}>
                      <Area type="monotone" dataKey="value" stroke="#3b82f6" fill="#3b82f6" />
                   </AreaChart>
                </ResponsiveContainer>
              </div>
          </div>
          <div className="bg-alpha-card border border-gray-700 p-6 rounded-2xl">
              <p className="text-gray-400 text-xs font-bold uppercase mb-1">Total Unrealized P&L</p>
              <h2 className={`text-3xl font-bold font-mono ${totalPnL >= 0 ? 'text-alpha-success' : 'text-alpha-danger'}`}>
                  {totalPnL >= 0 ? '+' : ''}${Math.abs(totalPnL).toLocaleString(undefined, {minimumFractionDigits: 2})}
              </h2>
          </div>
      </div>

      <div className="bg-alpha-card border border-gray-700 rounded-2xl overflow-hidden shadow-2xl">
          <div className="p-4 border-b border-gray-700 bg-gray-800/50 flex items-center justify-between">
              <h3 className="font-bold text-white flex items-center gap-2">
                <Icons.Chart size={18} className="text-alpha-success" />
                Active Positions
              </h3>
              <div className="flex items-center gap-2">
                 <span className="text-[10px] font-bold text-alpha-success bg-alpha-success/10 px-2 py-1 rounded-full animate-pulse border border-alpha-success/20">LIVE MARKET DATA</span>
              </div>
          </div>
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-gray-800/30 text-xs text-gray-400 uppercase">
                      <tr>
                          <th className="px-6 py-4">Ticker</th>
                          <th className="px-6 py-4 text-right">Market Price</th>
                          <th className="px-6 py-4 text-right">Position Value</th>
                          <th className="px-6 py-4 text-right">Day Chg</th>
                          <th className="px-6 py-4 text-right">Total P&L</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-800">
                      {items.length > 0 ? items.map(item => {
                          const price = item.currentPrice || item.avgPrice;
                          const value = price * item.quantity;
                          const pnl = value - (item.avgPrice * item.quantity);
                          return (
                              <tr key={item.id} className="hover:bg-gray-800/50 transition-colors group">
                                  <td className="px-6 py-4 font-bold text-white">
                                      <div className="flex flex-col">
                                        <span>{item.ticker}</span>
                                        <span className="text-[10px] text-gray-500 font-normal">Qty: {item.quantity} @ ${item.avgPrice.toFixed(2)}</span>
                                      </div>
                                  </td>
                                  <td className="px-6 py-4 text-right font-mono text-gray-300">
                                    <div className="flex flex-col items-end">
                                      <span>${price.toFixed(2)}</span>
                                    </div>
                                  </td>
                                  <td className="px-6 py-4 text-right text-white font-bold font-mono">
