import GameRoomDetailView from './components/GameRoomDetailView';
import { View, Portfolio, WatchlistItem, GameRoom } from './types';
import { MOCK_PORTFOLIOS, MOCK_GAME_ROOMS } from './services/mockData';
import { Icons } from './components/Icons';
import { fetchStockQuote } from './services/stockData';

const CONTEST_TYPES = [
  { id: 'daily', title: 'Daily Sprint', prize: '1,000', expiry: '1 Day', color: 'from-orange-500 to-red-600', icon: <Icons.Zap size={24} className="text-white" />, description: 'Intraday performance battle.' },
  { id: 'monthly', title: 'Monthly Marathon', prize: '5,000', expiry: '1 Month', color: 'from-blue-600 to-indigo-600', icon: <Icons.Trophy size={24} className="text-white" />, description: 'Long-term strategy test.' },
  { id: 'yearly', title: 'Legends League', prize: '50,000', expiry: '1 Year', color: 'from-purple-600 to-fuchsia-600', icon: <Icons.Crown size={24} className="text-white" />, description: 'For the visionary investors.' },
];

interface Toast { id: number; message: string; type: 'success' | 'error' | 'info'; }

function App() {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [virtualBalance, setVirtualBalance] = useState(100);
  const [portfolios, setPortfolios] = useState<Portfolio[]>(MOCK_PORTFOLIOS);
  const [gameRooms, setGameRooms] = useState<GameRoom[]>(MOCK_GAME_ROOMS);
  const [backedIds, setBackedIds] = useState<string[]>([]);
  const [isKOL, setIsKOL] = useState(false);
  const [streakDays, setStreakDays] = useState(0);
  const [isSyncing, setIsSyncing] = useState(false);

  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);
  const [selectedGameRoom, setSelectedGameRoom] = useState<GameRoom | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchType, setSearchType] = useState<'PORTFOLIOS' | 'ROOMS'>('PORTFOLIOS');
  const [showBonusModal, setShowBonusModal] = useState(false);
  const [bonusAmount, setBonusAmount] = useState(0);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [watchlist, setWatchlist] = useState<WatchlistItem[]>([
      { id: '1', ticker: 'TSLA', quantity: 10, avgPrice: 165.00 }
  ]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3000);
  };

  /**
   * Universal Sync Engine: Iterates through all portfolios and watchlist items
   * to replace "artificial" prices with real-time market data from Gemini Search.
   */
  const syncAllPrices = async () => {
    if (isSyncing) return;
    setIsSyncing(true);

    // Aggregate all unique tickers
    const tickers = new Set<string>();
    watchlist.forEach(w => tickers.add(w.ticker));
    portfolios.forEach(p => p.stocks.forEach(s => tickers.add(s.ticker)));

    const tickerList = Array.from(tickers);
    const updatedMarketMap: Record<string, any> = {};

    try {
      // Fetch data sequentially to respect search tool boundaries
      for (const ticker of tickerList) {
        const res = await fetchStockQuote(ticker);
        updatedMarketMap[ticker] = res.stock;
      }

      // Update Portfolios State
      setPortfolios(prev => prev.map(p => {
        const updatedStocks = p.stocks.map(s => updatedMarketMap[s.ticker] || s);
        const avgReturn = updatedStocks.reduce((sum, s) => sum + s.changePercent, 0) / updatedStocks.length;
        return { ...p, stocks: updatedStocks, totalReturn: Number(avgReturn.toFixed(2)) };
      }));

      // Update Watchlist State
      setWatchlist(prev => prev.map(w => {
        const market = updatedMarketMap[w.ticker];
        return market ? { ...w, currentPrice: market.price, dayChangePercent: market.changePercent } : w;
      }));

      addToast("Real-time prices synchronized.", "success");
    } catch (e) {
      console.error("Global price sync failed", e);
      addToast("Network sync failed. Retrying shortly...", "error");
    } finally {
      setIsSyncing(false);
    }
  };

  // Run global sync on application boot
  useEffect(() => {
    syncAllPrices();
  }, []);

  // Periodic Refresh every 5 minutes
  useEffect(() => {
    const interval = setInterval(() => syncAllPrices(), 300000);
    return () => clearInterval(interval);
  }, [watchlist, portfolios]);

  const handleBackPortfolio = (id: string, amount: number) => {
    if (virtualBalance < amount) {
      addToast("Insufficient virtual balance!", "error");
      return;
    }
    setVirtualBalance(prev => prev - amount);
    setBackedIds(prev => [...prev, id]);
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, backers: p.backers + 1 } : p));
    addToast(`Backed portfolio with $${amount}!`, "success");
  };

  const handleAddToWatchlist = (ticker: string, quantity: number, avgPrice: number) => {
      const newItem: WatchlistItem = { id: Date.now().toString(), ticker: ticker.toUpperCase(), quantity, avgPrice, currentPrice: avgPrice };
      setWatchlist(prev => [...prev, newItem]);
      addToast(`${ticker.toUpperCase()} tracked.`, "success");
      syncAllPrices();
  };

  const renderContent = () => {
    if (selectedPortfolio) return <PortfolioDetailView portfolio={selectedPortfolio} onBack={() => setSelectedPortfolio(null)} onWager={handleBackPortfolio} userBalance={virtualBalance} isBacked={backedIds.includes(selectedPortfolio.id)} />;
    if (selectedGameRoom) return <GameRoomDetailView room={selectedGameRoom} portfolios={portfolios} onBack={() => setSelectedGameRoom(null)} onJoin={() => addToast("Request sent", "info")} onViewPortfolio={setSelectedPortfolio} onBackPortfolio={handleBackPortfolio} userBalance={virtualBalance} backedIds={backedIds} />;

    switch (currentView) {
      case View.HOME:
        return (
          <div className="space-y-8">
            <div className="relative rounded-2xl overflow-hidden glass p-10 border-blue-500/30">
              <h1 className="text-5xl font-bold text-white mb-4">Real-Time <span className="text-alpha-success">Alpha.</span></h1>
              <p className="text-gray-400 max-w-lg mb-8">Fantasy sports meets the actual stock market. Back strategies tied to live prices fetched directly from Google Finance.</p>

              <div className="flex bg-black/40 p-2 rounded-2xl border border-gray-600 max-w-lg">
                  <Icons.Search className="m-3 text-gray-500" />
                  <input 
                    type="text" 
                    placeholder="Search tickers or KOLs..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="flex-1 bg-transparent text-white outline-none" 
                  />
              </div>
            </div>

            <div className="flex items-center justify-between">
                <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                    <Icons.Flame className="text-orange-500" /> Trending Now
                    {isSyncing && <Icons.Clock className="text-alpha-accent animate-spin" size={18} />}
                </h2>
                <button onClick={syncAllPrices} disabled={isSyncing} className="text-xs text-alpha-accent hover:underline flex items-center gap-1">
                    <Icons.Zap size={12}/> Refresh Prices
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {portfolios.map(p => <PortfolioCard key={p.id} portfolio={p} onBack={handleBackPortfolio} isBacked={backedIds.includes(p.id)} userBalance={virtualBalance} onView={setSelectedPortfolio} />)}
            </div>
          </div>
        );
      case View.WATCHLIST: return <WatchlistPanel watchlist={watchlist} addToWatchlist={handleAddToWatchlist} />;
      case View.CONTESTS: return <div className="p-10 text-center text-gray-500">Global Contests Coming Soon</div>;
      case View.ADMIN: return <AdminPanel isKOL={isKOL} onVerifyKOL={(code) => { if(code==='ALPHA2024'){setIsKOL(true); return true;} return false; }} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-gray-100 sm:pl-64">
      <Navbar currentView={currentView} setView={setCurrentView} virtualBalance={virtualBalance} streakDays={streakDays} />
      <main className="pt-24 px-8 max-w-7xl mx-auto pb-10">{renderContent()}</main>
      {showBonusModal && <BonusModal bonusAmount={bonusAmount} streakDays={streakDays} onClose={() => setShowBonusModal(false)} />}
      <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2">
          {toasts.map(t => (
              <div key={t.id} className="bg-gray-900 border border-gray-700 p-4 rounded-xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-right-10">
                  <Icons.Zap className="text-alpha-accent" size={18} />
                  <span className="text-sm font-bold">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
}

