import { GoogleGenAI } from "@google/genai";
import { Stock } from '../types';

export interface StockQuoteResponse {
  stock: Stock;
  sources: { title: string; uri: string }[];
}

// Session cache to prevent repeated search calls for the same ticker in a single session
const QUOTE_CACHE: Record<string, { data: StockQuoteResponse, timestamp: number }> = {};
const CACHE_DURATION = 60 * 1000; // 1 minute

/**
 * Fetches real-time stock data using Gemini 3 with Google Search Grounding.
 * Specifically instructs the model to prioritize Google Finance for data accuracy.
 */
export const fetchStockQuote = async (ticker: string): Promise<StockQuoteResponse> => {
  const upperTicker = ticker.toUpperCase();
  const now = Date.now();

  // Return cached data if available and fresh
  if (QUOTE_CACHE[upperTicker] && (now - QUOTE_CACHE[upperTicker].timestamp < CACHE_DURATION)) {
    return QUOTE_CACHE[upperTicker].data;
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // We use gemini-3-flash-preview for fast search-grounded queries
    const prompt = `
      Search Google Finance for the CURRENT real-time stock market price and the today's percentage change for ticker symbol "${upperTicker}".
      Identify the exact last price and the change percentage from the most reliable recent result.

      Return ONLY a JSON object with this structure:
      {
        "ticker": "${upperTicker}",
        "price": number,
        "changePercent": number,
        "name": "string"
      }

      Do not include any other text or markdown formatting except the JSON.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0, // Deterministic output
      }
    });

    const text = response.text || '';
    // Use a regex to extract JSON from possible markdown wrappers
    const jsonMatch = text.match(/\{[\s\S]*\}/);

    if (!jsonMatch) {
      throw new Error("No JSON found in model response");
    }

    const data = JSON.parse(jsonMatch[0]);

    // Extract grounding sources
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
      .filter((chunk: any) => chunk.web)
      .map((chunk: any) => ({
        title: chunk.web.title,
        uri: chunk.web.uri
      }));

    const result: StockQuoteResponse = {
      stock: {
        ticker: upperTicker,
        name: data.name || upperTicker,
        price: Number(data.price),
        changePercent: Number(data.changePercent),
        sector: 'Market'
      },
      sources: sources
    };

    // Update cache
    QUOTE_CACHE[upperTicker] = { data: result, timestamp: now };
    return result;

  } catch (error) {
    console.error(`Real-time fetch failed for ${upperTicker}:`, error);

    // If it fails, return a stock object with 0 price to signify "Syncing/Error"
    // rather than a random artificial price.
    return {
      stock: {
        ticker: upperTicker,
        name: 'Market Asset',
        price: 0,
        changePercent: 0,
        sector: 'Unknown'
      },
      sources: []
    };
  }
};

/**
 * Visual "Tick" effect to simulate live markets between real API refreshes.
 * This should only be used for UI micro-movements.
 */
export const getLivePriceUpdate = (currentPrice: number): number => {
  if (currentPrice <= 0) return currentPrice;
  const volatility = 0.0002; // Very low volatility for ticks
  const change = currentPrice * volatility * (Math.random() - 0.5);
  return Number((currentPrice + change).toFixed(2));
};

export const generateHistoricalData = (basePrice: number, points: number = 30) => {
  const data = [];
  let current = basePrice * 0.98;
  for (let i = 0; i < points; i++) {
    const volatility = 0.01;
    current = current * (1 + (Math.random() * volatility - volatility/2));
    data.push({
      time: `T-${points-i}`,
      value: Number(current.toFixed(2))
    });
  }
  return data;
};

import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import PortfolioCard from './components/PortfolioCard';
import PortfolioDetailView from './components/PortfolioDetailView';
import WatchlistPanel from './components/WatchlistPanel';
import AdminPanel from './components/AdminPanel';
import BonusModal from './components/BonusModal';
import GameRoomCard from './components/GameRoomCard';
import GameRoomDetailView from './components/GameRoomDetailView';
import { View, Portfolio, WatchlistItem, GameRoom } from './types';
import { MOCK_PORTFOLIOS, MOCK_GAME_ROOMS } from './services/mockData';
import { Icons } from './components/Icons';
import { fetchStockQuote } from './services/stockData';

const CONTEST_TYPES = [
  { id: 'daily', title: 'Daily Sprint', prize: '1,000', expiry: '1 Day', color: 'from-orange-500 to-red-600', icon: <Icons.Zap size={24} className="text-white" />, description: 'Intraday performance battle.' },
  { id: 'monthly', title: 'Monthly Marathon', prize: '5,000', expiry: '1 Month', color: 'from-blue-600 to-indigo-600', icon: <Icons.Trophy size={24} className="text-white" />, description: 'Long-term strategy test.' },
  { id: 'yearly', title: 'Legends League', prize: '50,000', expiry: '1 Year', color: 'from-purple-600 to-fuchsia-600', icon: <Icons.Crown size={24} className="text-white" />, description: 'For the visionary investors.' },
];

interface Toast { id: number; message: string; type: 'success' | 'error' | 'info'; }

function App() {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [virtualBalance, setVirtualBalance] = useState(100);
  const [portfolios, setPortfolios] = useState<Portfolio[]>(MOCK_PORTFOLIOS);
  const [gameRooms, setGameRooms] = useState<GameRoom[]>(MOCK_GAME_ROOMS);
  const [backedIds, setBackedIds] = useState<string[]>([]);
  const [isKOL, setIsKOL] = useState(false);
  const [streakDays, setStreakDays] = useState(0);
  const [isSyncing, setIsSyncing] = useState(false);

  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);
  const [selectedGameRoom, setSelectedGameRoom] = useState<GameRoom | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchType, setSearchType] = useState<'PORTFOLIOS' | 'ROOMS'>('PORTFOLIOS');
  const [showBonusModal, setShowBonusModal] = useState(false);
  const [bonusAmount, setBonusAmount] = useState(0);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [watchlist, setWatchlist] = useState<WatchlistItem[]>([
      { id: '1', ticker: 'NVDA', quantity: 1, avgPrice: 100.00 },
      { id: '2', ticker: 'TSLA', quantity: 10, avgPrice: 165.00 }
  ]);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3000);
  };

  /**
   * Universal Sync Engine: Iterates through all portfolios and watchlist items
   * to replace "artificial" prices with real-time market data from Gemini Search.
   */
  const syncAllPrices = useCallback(async () => {
    if (isSyncing) return;
    setIsSyncing(true);

    // Aggregate all unique tickers
    const tickers = new Set<string>();
    watchlist.forEach(w => tickers.add(w.ticker));
    portfolios.forEach(p => p.stocks.forEach(s => tickers.add(s.ticker)));

    const tickerList = Array.from(tickers);
    const updatedMarketMap: Record<string, any> = {};

    try {
      // Fetch data sequentially to respect tool constraints and prevent noise
      for (const ticker of tickerList) {
        const res = await fetchStockQuote(ticker);
        if (res.stock.price > 0) {
          updatedMarketMap[ticker] = res.stock;
        }
      }

      // Update Portfolios State with real returns
      setPortfolios(prev => prev.map(p => {
        const updatedStocks = p.stocks.map(s => updatedMarketMap[s.ticker] || s);
        const avgReturn = updatedStocks.reduce((sum, s) => sum + s.changePercent, 0) / updatedStocks.length;
        return { 
          ...p, 
          stocks: updatedStocks, 
          totalReturn: Number(avgReturn.toFixed(2)) 
        };
      }));

      // Update Watchlist State
      setWatchlist(prev => prev.map(w => {
        const market = updatedMarketMap[w.ticker];
        return market ? { 
          ...w, 
          currentPrice: market.price, 
          dayChangePercent: market.changePercent 
        } : w;
      }));

      addToast("Market data updated live.", "success");
    } catch (e) {
      console.error("Global price sync failed", e);
      addToast("Sync error. Using last known data.", "error");
    } finally {
      setIsSyncing(false);
    }
  }, [isSyncing, watchlist, portfolios]);

  // Initial Sync
  useEffect(() => {
    syncAllPrices();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Only on mount

  // Periodic Refresh
  useEffect(() => {
    const interval = setInterval(() => {
      syncAllPrices();
    }, 180000); // 3 minutes refresh
    return () => clearInterval(interval);
  }, [syncAllPrices]);

  const handleBackPortfolio = (id: string, amount: number) => {
    if (virtualBalance < amount) {
      addToast("Insufficient virtual balance!", "error");
      return;
    }
    setVirtualBalance(prev => prev - amount);
    setBackedIds(prev => [...prev, id]);
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, backers: p.backers + 1 } : p));
    addToast(`Backed portfolio with $${amount}!`, "success");
  };

  const handleAddToWatchlist = (ticker: string, quantity: number, avgPrice: number) => {
      const tickerUpper = ticker.toUpperCase();
      const existing = watchlist.find(w => w.ticker === tickerUpper);
      if (existing) {
          addToast(`${tickerUpper} is already in your watchlist.`, "info");
          return;
      }
      const newItem: WatchlistItem = { id: Date.now().toString(), ticker: tickerUpper, quantity, avgPrice, currentPrice: avgPrice };
      setWatchlist(prev => [...prev, newItem]);
      addToast(`${tickerUpper} added.`, "success");
      // Trigger immediate sync for the new item
      setTimeout(() => syncAllPrices(), 100);
  };

  const renderContent = () => {
    if (selectedPortfolio) return <PortfolioDetailView portfolio={selectedPortfolio} onBack={() => setSelectedPortfolio(null)} onWager={handleBackPortfolio} userBalance={virtualBalance} isBacked={backedIds.includes(selectedPortfolio.id)} />;
    if (selectedGameRoom) return <GameRoomDetailView room={selectedGameRoom} portfolios={portfolios} onBack={() => setSelectedGameRoom(null)} onJoin={() => addToast("Request sent", "info")} onViewPortfolio={setSelectedPortfolio} onBackPortfolio={handleBackPortfolio} userBalance={virtualBalance} backedIds={backedIds} />;

    switch (currentView) {
      case View.HOME:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="relative rounded-3xl overflow-hidden glass p-10 border-blue-500/20 shadow-2xl">
              <div className="relative z-10">
                <h1 className="text-5xl font-extrabold text-white mb-4 leading-tight">
                  Actual Market <br/><span className="text-alpha-success">Real-Time Data.</span>
                </h1>
                <p className="text-gray-400 max-w-lg mb-8 text-lg font-medium">
                  Track live tickers fetched directly from Google Finance. No more artificial prices—play with the real pulse of Wall Street.
                </p>

                <div className="flex bg-black/50 p-3 rounded-2xl border border-gray-700 max-w-lg shadow-inner">
                    <Icons.Search className="m-3 text-gray-400" size={24} />
                    <input 
                      type="text" 
                      placeholder="Search tickers (e.g. NVDA, BTC, AAPL)..." 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="flex-1 bg-transparent text-white outline-none placeholder-gray-600 font-bold text-lg" 
                    />
                </div>
              </div>
              {/* Abstract decorative elements */}
              <div className="absolute top-0 right-0 -mt-20 -mr-20 w-80 h-80 bg-alpha-accent/10 rounded-full blur-3xl animate-pulse-slow"></div>
            </div>

            <div className="flex items-center justify-between">
                <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                    <Icons.Flame className="text-orange-500 animate-float" /> Top Strategies
                    {isSyncing && <Icons.Clock className="text-alpha-accent animate-spin" size={18} />}
                </h2>
                <div className="flex items-center gap-4">
                  <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest border border-gray-800 px-3 py-1 rounded-full">
                    Refresh rate: 3m
                  </span>
                  <button onClick={syncAllPrices} disabled={isSyncing} className="bg-gray-800 hover:bg-gray-700 disabled:opacity-50 text-white text-xs font-bold px-4 py-2 rounded-xl border border-gray-700 transition-all active:scale-95 flex items-center gap-2">
                      <Icons.Zap size={14} className={isSyncing ? 'animate-pulse' : ''} /> Sync Now
                  </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {(searchQuery 
                  ? portfolios.filter(p => p.stocks.some(s => s.ticker.includes(searchQuery.toUpperCase())) || p.title.toLowerCase().includes(searchQuery.toLowerCase()))
                  : portfolios
                ).map(p => <PortfolioCard key={p.id} portfolio={p} onBack={handleBackPortfolio} isBacked={backedIds.includes(p.id)} userBalance={virtualBalance} onView={setSelectedPortfolio} />)}
            </div>
          </div>
        );
      case View.WATCHLIST: return <WatchlistPanel watchlist={watchlist} addToWatchlist={handleAddToWatchlist} />;
      case View.CONTESTS: return <div className="p-20 text-center text-gray-500 font-bold border border-gray-800 border-dashed rounded-3xl">Contests are currently syncing with live events.</div>;
      case View.ADMIN: return <AdminPanel isKOL={isKOL} onVerifyKOL={(code) => { if(code==='ALPHA2024'){setIsKOL(true); return true;} return false; }} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-gray-100 sm:pl-64 transition-all duration-500">
      <Navbar currentView={currentView} setView={setCurrentView} virtualBalance={virtualBalance} streakDays={streakDays} />
      <main className="pt-24 px-8 max-w-7xl mx-auto pb-10">{renderContent()}</main>
      {showBonusModal && <BonusModal bonusAmount={bonusAmount} streakDays={streakDays} onClose={() => setShowBonusModal(false)} />}
      <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2">
          {toasts.map(t => (
              <div key={t.id} className="bg-alpha-card border border-gray-700 p-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-right-10 backdrop-blur-xl bg-opacity-80">
                  <div className={`p-2 rounded-lg ${t.type === 'success' ? 'bg-alpha-success/20 text-alpha-success' : 'bg-alpha-accent/20 text-alpha-accent'}`}>
                    <Icons.Zap size={18} />
                  </div>
                  <span className="text-sm font-bold text-white">{t.message}</span>
              </div>
          ))}
      </div>
    </div>
  );
}

export default App;

