import { GoogleGenAI } from "@google/genai";
import { Stock, ChartDataPoint } from "../types";

const CACHE: Record<string, { price: number; change: number; timestamp: number }> = {};
const CACHE_TTL = 1000 * 60 * 3; // 3 minutes cache for real-time accuracy

/**
 * Fetches a single real-time price using Gemini Search Grounding.
 * Uses a strict prompt to ensure JSON-only output.
 */
export const fetchRealTimePrice = async (ticker: string): Promise<{ price: number; change: number }> => {
  const upperTicker = ticker.toUpperCase();
  const now = Date.now();

  if (CACHE[upperTicker] && now - CACHE[upperTicker].timestamp < CACHE_TTL) {
    return { price: CACHE[upperTicker].price, change: CACHE[upperTicker].change };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Search Google Finance for the EXACT current real-time stock price and today's percentage change for ticker "${upperTicker}". 
    Return ONLY a raw JSON object: {"price": number, "change": number}. 
    Ensure the "price" is a float and "change" is a float representing percentage.
    Do not include any other text, markdown, or explanation.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0,
      }
    });

    const text = response.text || "{}";
    // Sanitize output to find JSON object even if model includes markdown wrappers
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const data = JSON.parse(jsonMatch[0]);
      if (typeof data.price === 'number') {
        const result = { 
          price: Number(data.price), 
          change: Number(data.change || 0) 
        };
        CACHE[upperTicker] = { ...result, timestamp: now };
        return result;
      }
    }
  } catch (error) {
    console.error(`Error fetching real-time price for ${upperTicker}:`, error);
  }

  return { price: 0, change: 0 }; 
};

/**
 * Fetches comprehensive stock data and sources for search grounding display.
 */
export const fetchStockQuote = async (ticker: string): Promise<{ stock: Stock, sources: {title: string, uri: string}[] }> => {
  const upperTicker = ticker.toUpperCase();
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Provide the current price, percentage change, and full company name for ${upperTicker} based on real-time data.
    Also return grounding sources. Output JSON: {"price": number, "change": number, "name": "string"}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.filter(chunk => chunk.web)
      .map((chunk: any) => ({
        title: chunk.web.title || 'Source',
        uri: chunk.web.uri || '#'
      })) || [];

    const text = response.text || "";
    const jsonMatch = text.match(/\{[\s\S]*\}/);

    let price = 0;
    let change = 0;
    let name = upperTicker;

    if (jsonMatch) {
      const data = JSON.parse(jsonMatch[0]);
      price = Number(data.price) || 0;
      change = Number(data.change) || 0;
      name = data.name || upperTicker;
    }

    return {
      stock: {
        ticker: upperTicker,
        name: name,
        price: price,
        changePercent: change
      },
      sources
    };
  } catch (error) {
    console.error("Quote Error:", error);
    return {
      stock: { ticker: upperTicker, name: 'Market Asset', price: 0, changePercent: 0 },
      sources: []
    };
  }
};

export const getLivePriceUpdate = (currentPrice: number): number => {
  return getLiveTick(currentPrice);
};

export const generateHistoricalData = (currentValue: number): ChartDataPoint[] => {
  const data: ChartDataPoint[] = [];
  const now = new Date();
  const count = 20;
  for (let i = count; i >= 0; i--) {
    const time = new Date(now.getTime() - i * 1000 * 60 * 60 * 24);
    // Generate realistic random walk
    const factor = 0.95 + (Math.random() * 0.1);
    data.push({
      time: time.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      value: Number((currentValue * factor).toFixed(2))
    });
  }
  return data;
};

export const getLiveTick = (price: number): number => {
  if (price <= 0) return price;
  const movement = price * 0.00015 * (Math.random() - 0.5);
  return Number((price + movement).toFixed(2));
};

import React, { useState, useEffect, useCallback } from 'react';
import { Icons } from './components/Icons';
import Navbar from './components/Navbar';
import WatchlistPanel from './components/WatchlistPanel';
import PortfolioDetailView from './components/PortfolioDetailView';
import AdminPanel from './components/AdminPanel';
import { View, Portfolio, Stock, Contest, WatchlistItem } from './types';
import { INITIAL_PORTFOLIOS, CONTEST_LOBBY } from './services/mockData';
import { fetchRealTimePrice, getLiveTick } from './services/stockData';
import { analyzePortfolioWithGemini } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DISCOVER);
  const [portfolios, setPortfolios] = useState<Portfolio[]>(INITIAL_PORTFOLIOS);
  const [watchlist, setWatchlist] = useState<WatchlistItem[]>([
    { id: 'w1', ticker: 'NVDA', currentPrice: 0, dayChangePercent: 0 },
    { id: 'w2', ticker: 'AAPL', currentPrice: 0, dayChangePercent: 0 }
  ]);
  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);
  const [balance, setBalance] = useState(100.00);
  const [streak, setStreak] = useState(1);
  const [isSyncing, setIsSyncing] = useState(false);
  const [aiAnalyses, setAiAnalyses] = useState<Record<string, string>>({});
  const [loadingAi, setLoadingAi] = useState<Record<string, boolean>>({});
  const [backedIds, setBackedIds] = useState<string[]>([]);

  // Sync real-time prices for all visible assets
  const syncPrices = useCallback(async () => {
    if (isSyncing) return;
    setIsSyncing(true);

    const uniqueTickers = Array.from(new Set([
      ...portfolios.flatMap(p => p.stocks.map(s => s.ticker)),
      ...watchlist.map(w => w.ticker)
    ])) as string[];

    const priceMap: Record<string, { price: number, change: number }> = {};

    // Fetch prices in parallel to improve performance
    await Promise.all(uniqueTickers.map(async (ticker) => {
      const result = await fetchRealTimePrice(ticker);
      priceMap[ticker] = result;
    }));

    // Update Portfolios
    setPortfolios(prev => prev.map(p => {
      const updatedStocks = p.stocks.map(s => ({
        ...s,
        price: priceMap[s.ticker]?.price || s.price,
        changePercent: priceMap[s.ticker]?.change || s.changePercent
      }));
      const avgReturn = updatedStocks.reduce((sum, s) => sum + s.changePercent, 0) / updatedStocks.length;
      return {
        ...p,
        stocks: updatedStocks,
        totalReturn: Number(avgReturn.toFixed(1))
      };
    }));

    // Update Watchlist
    setWatchlist(prev => prev.map(w => ({
      ...w,
      currentPrice: priceMap[w.ticker]?.price || w.currentPrice,
      dayChangePercent: priceMap[w.ticker]?.change || w.dayChangePercent
    })));

    setIsSyncing(false);
  }, [isSyncing, portfolios, watchlist]);

  useEffect(() => {
    syncPrices();
  }, []);

  // Visual "Live" Ticking Effect for active prices
  useEffect(() => {
    const interval = setInterval(() => {
      setPortfolios(prev => prev.map(p => ({
        ...p,
        stocks: p.stocks.map(s => ({ ...s, price: getLiveTick(s.price) }))
      })));
      setWatchlist(prev => prev.map(w => ({
        ...w,
        currentPrice: w.currentPrice ? getLiveTick(w.currentPrice) : 0
      })));
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  const handleRevealAnalysis = async (e: React.MouseEvent, portfolio: Portfolio) => {
    e.stopPropagation();
    if (aiAnalyses[portfolio.id]) return;
    setLoadingAi(prev => ({ ...prev, [portfolio.id]: true }));
    const result = await analyzePortfolioWithGemini(portfolio.stocks, portfolio.title);
    setAiAnalyses(prev => ({ ...prev, [portfolio.id]: result }));
    setLoadingAi(prev => ({ ...prev, [portfolio.id]: false }));
  };

  const handleBackPortfolio = (id: string, amount: number) => {
    if (balance >= amount) {
      setBalance(prev => prev - amount);
      setBackedIds(prev => [...prev, id]);
      setPortfolios(prev => prev.map(p => p.id === id ? { ...p, backers: p.backers + 1 } : p));
    }
  };

  const handleAddToWatchlist = (ticker: string) => {
    const upper = ticker.toUpperCase();
    if (watchlist.some(w => w.ticker === upper)) return;
    const newItem: WatchlistItem = {
      id: `w-${Date.now()}`,
      ticker: upper,
      currentPrice: 0,
      dayChangePercent: 0
    };
    setWatchlist(prev => [...prev, newItem]);
    syncPrices();
  };

  const handleViewPortfolio = (p: Portfolio) => {
    setSelectedPortfolio(p);
  };

  const renderPortfolioCard = (p: Portfolio) => (
    <div 
      key={p.id} 
      onClick={() => handleViewPortfolio(p)}
      className="bg-alpha-card border border-gray-700/50 rounded-2xl overflow-hidden transition-all hover:border-blue-500/30 group cursor-pointer"
    >
      <div className="p-5 flex justify-between items-start">
        <div className="flex gap-3 items-center">
          <img src={p.kolAvatar} alt={p.kolName} className="w-10 h-10 rounded-full object-cover border border-gray-600" />
          <div>
            <div className="flex items-center gap-1">
              <span className="font-bold text-white text-sm group-hover:text-blue-400 transition-colors">{p.title}</span>
            </div>
            <div className="flex items-center gap-1 text-[11px] text-gray-400">
              <span>by {p.kolName}</span>
              {p.isVerified && <Icons.ShieldCheck size={12} className="text-blue-400" />}
            </div>
          </div>
        </div>
        <div className={`px-2 py-0.5 rounded text-[11px] font-bold ${p.totalReturn >= 0 ? 'bg-green-500/10 text-green-400' : 'bg-red-500/10 text-red-400'}`}>
          {p.totalReturn >= 0 ? '+' : ''}{p.totalReturn}%
        </div>
      </div>

      <div className="px-5 pb-2 grid grid-cols-2 gap-x-6 gap-y-4">
        {p.stocks.map(s => (
          <div key={s.ticker} className="flex flex-col">
            <div className="flex justify-between items-center mb-0.5">
              <span className="font-bold text-xs text-white">{s.ticker}</span>
              <span className={`text-[10px] font-bold ${s.changePercent >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                {s.changePercent >= 0 ? '+' : ''}{s.changePercent}%
              </span>
            </div>
            <span className="text-[10px] text-gray-500 font-mono">${s.price > 0 ? s.price.toFixed(2) : 'Syncing...'}</span>
          </div>
        ))}
      </div>

      <div className="p-5 pt-3 flex flex-col gap-4">
        <div className="h-[1px] bg-gray-700/50 w-full" />

        {aiAnalyses[p.id] ? (
          <div className="text-[11px] text-gray-300 bg-blue-500/5 p-3 rounded-xl border border-blue-500/10 animate-in fade-in slide-in-from-top-1">
            {aiAnalyses[p.id]}
          </div>
        ) : (
          <button 
            onClick={(e) => handleRevealAnalysis(e, p)}
            disabled={loadingAi[p.id]}
            className="flex items-center justify-center gap-2 text-[11px] font-bold text-blue-400 hover:text-blue-300 transition-colors py-1 disabled:opacity-50"
          >
            <Icons.Zap size={14} className="fill-blue-400" />
            {loadingAi[p.id] ? 'Analyzing...' : 'Reveal AI Analysis'}
          </button>
        )}

        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2 text-[11px] text-gray-500 font-medium">
            <Icons.Users size={14} />
            <span>{p.backers} Backers</span>
          </div>
          <button 
            disabled={backedIds.includes(p.id)}
            className={`font-bold text-xs px-4 py-2 rounded-lg transition-all flex items-center gap-2 ${backedIds.includes(p.id) ? 'bg-gray-700 text-gray-400' : 'bg-green-500/90 hover:bg-green-500 text-white'}`}
          >
            {backedIds.includes(p.id) ? 'Backed' : 'Back It'} <Icons.TrendingUp size={14} />
          </button>
        </div>
      </div>
    </div>
  );

  const renderCurrentView = () => {
    if (selectedPortfolio) {
      return (
        <PortfolioDetailView 
          portfolio={selectedPortfolio} 
          onBack={() => setSelectedPortfolio(null)} 
          onWager={handleBackPortfolio} 
          userBalance={balance} 
          isBacked={backedIds.includes(selectedPortfolio.id)} 
        />
      );
    }

    switch (currentView) {
      case View.DISCOVER:
      case View.HOME:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="bg-alpha-card/50 border border-blue-500/10 rounded-3xl p-10 relative overflow-hidden group">
              <div className="absolute inset-0 bg-gradient-to-br from-blue-600/5 to-transparent pointer-events-none" />
              <div className="relative z-10 max-w-2xl">
                <span className="inline-block py-1 px-3 rounded-full bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] font-bold uppercase tracking-widest mb-4">Beta Access V1.0</span>
                <h1 className="text-5xl font-extrabold text-white mb-4 leading-tight">
                  Track. Compete.<br/><span className="text-blue-500">Real-Time Markets.</span>
                </h1>

                <div className="mt-8 bg-gray-900/80 rounded-2xl border border-gray-700 p-2 flex items-center gap-2 focus-within:border-blue-500/50 transition-all max-w-md">
                  <Icons.Search size={20} className="text-gray-500 ml-3" />
                  <input 
                    type="text" 
                    placeholder="Search portfolios, tickers, KOLs..." 
                    className="bg-transparent border-none text-white outline-none flex-1 py-2 text-sm placeholder-gray-600 font-medium"
                  />
                </div>
                <div className="mt-4 flex gap-2">
                  <button className="bg-blue-600 hover:bg-blue-500 text-white text-xs font-bold px-5 py-2 rounded-xl transition-all shadow-lg shadow-blue-600/20">Public Portfolios</button>
                  <button className="bg-transparent hover:bg-gray-800 text-gray-400 text-xs font-bold px-5 py-2 rounded-xl transition-all">Game Rooms</button>
                </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold text-white flex items-center gap-2">
                  <Icons.Flame className="text-orange-500" /> Trending Portfolios
                </h2>
                <div className="flex items-center gap-4">
                  {isSyncing && <span className="text-[10px] text-blue-400 animate-pulse font-bold">Syncing Prices...</span>}
                  <button onClick={syncPrices} className="text-xs text-blue-400 hover:text-blue-300 font-bold transition-all">Refresh All</button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {portfolios.map(renderPortfolioCard)}
              </div>
            </div>
          </div>
        );

      case View.CONTESTS:
        return (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div>
              <h1 className="text-3xl font-bold text-white mb-1">Contest Lobby</h1>
              <p className="text-gray-400 text-sm">Battle it out with top-tier strategies.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {CONTEST_LOBBY.map(c => (
                <div key={c.id} className="bg-alpha-card border border-gray-700/50 rounded-3xl p-8 relative overflow-hidden group hover:border-blue-500/20 transition-all cursor-pointer">
                  <div className={`${c.color} w-12 h-12 rounded-2xl flex items-center justify-center mb-10 shadow-lg group-hover:scale-110 transition-transform`}>
                    {c.icon === 'Zap' && <Icons.Zap size={24} className="text-white fill-white" />}
                    {c.icon === 'Trophy' && <Icons.Trophy size={24} className="text-white" />}
                    {c.icon === 'Crown' && <Icons.Crown size={24} className="text-white" />}
                  </div>
                  <h3 className="text-xl font-bold text-white mb-2">{c.title}</h3>
                  <p className="text-gray-400 text-xs mb-8 leading-relaxed">{c.description}</p>
                  <div className="pt-6 border-t border-gray-700/50 flex justify-between items-center">
                    <span className="text-xl font-bold text-yellow-500">{c.prize}</span>
                    <span className="bg-gray-900 text-[10px] font-bold text-gray-500 px-3 py-1 rounded-full">{c.expiry}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="pt-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {portfolios.map(renderPortfolioCard)}
            </div>
          </div>
        );

      case View.WATCHLIST:
        return (
          <WatchlistPanel 
            watchlist={watchlist} 
            addToWatchlist={(ticker) => handleAddToWatchlist(ticker)} 
          />
        );

      case View.ADMIN:
        return <AdminPanel isKOL={false} onVerifyKOL={() => true} />;

      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-alpha-dark text-slate-200">
      <Navbar currentView={currentView} setView={(v) => { setCurrentView(v); setSelectedPortfolio(null); }} virtualBalance={balance} streakDays={streak} />
      <main className="sm:pl-64 pt-20 pb-20 sm:pb-10">
        <div className="p-4 sm:p-8 max-w-7xl mx-auto">
          {renderCurrentView()}
        </div>
      </main>
    </div>
  );
};

